INSERT INTO `buku` VALUES (8,1,'Ilmu Pengetahuan Alam untuk SMP/MTs Kelas VII (Edisi Revisi','disusun untuk membantu peserta didik memahami konsep-konsep dasar sains melalui kegiatan pembelajaran yang aktif, kontekstual, dan berbasis penyelidikan (inkuiri). Materi dikaitkan dengan fenomena yang sering dijumpai dalam kehidupan sehari-hari sehingga siswa dapat memahami hubungan antara ilmu pengetahuan dan lingkungan sekitar.\r\n\r\nSetiap bab dilengkapi dengan pertanyaan pemantik, tujuan pembelajaran, peta konsep, aktivitas eksperimen, latihan, proyek, dan asesmen yang mendorong siswa untuk berpikir kritis, kreatif, serta mampu memecahkan masalah secara ilmiah. Materi yang dipelajari meliputi hakikat sains dan metode ilmiah, zat dan perubahannya, suhu dan kalor, gerak dan gaya, klasifikasi makhluk hidup, ekologi dan keanekaragaman hayati Indonesia, serta bumi dan tata surya. \r\nmempersiapkan kalian membuat keputusan-keputusan penting di masa yang \r\nakan datang.',18,'victoriani inabuy','Pusat Kurikulum dan Perbukuan','2024',3,13,'tersedia',NULL,'Buku Ilmu Pengetahuan Alam untuk SMP/MTs Kelas VII merupakan buku ajar yang dikembangkan berdasarkan Kurikulum Merdeka untuk membangun kompetensi peserta didik dalam memahami konsep-konsep sains secara terpadu. Buku ini menggunakan pendekatan ilmiah melalui observasi, eksperimen, analisis data, dan pemecahan masalah sehingga siswa tidak hanya menguasai teori, tetapi juga mampu menerapkan pengetahuan dalam kehidupan sehari-hari. Penyajian materi yang sistematis, penggunaan bahasa yang mudah dipahami, ilustrasi yang menarik, serta berbagai aktivitas pembelajaran diharapkan dapat meningkatkan kemampuan berpikir kritis, literasi sains, kreativitas, dan karakter peserta didik sesuai Profil Pelajar Pancasila.','2026-07-10 14:14:47','2026-08-09 22:50:51'),(9,1,'Informatika untuk SMP/MTs Kelas VII (Edisi Revisi)','Buku Informatika untuk SMP/MTs Kelas VII (Edisi Revisi) membahas dasar-dasar ilmu informatika seperti berpikir komputasional, literasi digital, analisis data, serta algoritma dan pemrograman. Buku ini membantu siswa memahami teknologi, menggunakan perangkat digital secara bijak, dan mengembangkan kemampuan berpikir kritis serta kreatif.\r\ndan proses berpikir yang mencakup perangkat keras, perangkat lunak, dan menalar\r\n(reasoning) mengenai sistem dan persoalan. Moda berpikir (thinking mode) ini\r\ndidukung dan dilengkapi dengan pengetahuan teoretis dan praktis, serta teknik untuk\r\nmenganalisis, memodelkan, dan menyelesaikan persoalan.',30,'Maresha Caroline Wijanto','Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2023',3,3,'tersedia',NULL,'Buku Informatika untuk SMP/MTs Kelas VII bertujuan mengembangkan kemampuan siswa dalam memahami konsep informatika melalui pembelajaran berpikir komputasional, literasi digital, dan pemanfaatan teknologi. Materi disajikan melalui teori, aktivitas individu dan kelompok untuk meningkatkan kreativitas, kerja sama, serta kemampuan memecahkan masalah.','2026-07-10 14:32:42','2026-08-09 22:50:51'),(10,1,'Matematika untuk SMP/MTs Kelas VII','Buku Matematika Kelas VII SMP/MTs dirancang untuk membantu peserta didik memahami konsep-konsep dasar matematika sebagai bekal dalam kehidupan sehari-hari dan pembelajaran pada jenjang berikutnya. Materi yang disajikan meliputi bilangan bulat dan pecahan, aljabar, persamaan dan pertidaksamaan linear satu variabel, himpunan, perbandingan, aritmetika sosial, garis dan sudut, segitiga dan segiempat, penyajian data, serta peluang sederhana. Setiap bab diawali dengan permasalahan kontekstual yang dekat dengan kehidupan peserta didik, kemudian dilanjutkan dengan penjelasan konsep, contoh soal, latihan, aktivitas kelompok, dan evaluasi. Buku ini juga mendorong peserta didik untuk berpikir kritis, kreatif, logis, serta mampu memecahkan masalah melalui pendekatan pembelajaran yang aktif dan berbasis penalaran. Dengan penyajian yang sistematis, buku ini diharapkan dapat meningkatkan kemampuan literasi dan numerasi peserta didik serta menumbuhkan sikap percaya diri dalam mempelajari matematika.\r\nmatematika dengan menggunakan pendekatan yang lebih kontekstual melalui\r\npermasalahan kehidupan nyata dan melibatkan siswa secara aktif dalam\r\nbereksplorasi dengan pertanyaan penuntun. Sebagian besar pembelajaran\r\nmatematika dalam buku ini diupayakan menarik perhatian dan minat siswa\r\nsehingga ΓÇ£tidak merasa sedang belajar matematikaΓÇ¥.',30,'Dicky Susanto','Pusat Perbukuan','2022',3,5,'tersedia',NULL,'Buku Matematika Kelas VII SMP/MTs disusun sebagai bahan ajar untuk mengembangkan kemampuan berpikir logis, analitis, kritis, kreatif, dan sistematis peserta didik melalui pembelajaran matematika. Materi yang dibahas mencakup konsep bilangan, aljabar, persamaan linear satu variabel, himpunan, perbandingan, aritmetika sosial, geometri, penyajian data, dan peluang sederhana. Pembelajaran disajikan melalui pendekatan berbasis pemecahan masalah, kegiatan eksplorasi, latihan, serta evaluasi yang bertujuan meningkatkan pemahaman konsep dan keterampilan numerasi peserta didik. Selain menguasai materi, peserta didik diharapkan mampu menerapkan konsep matematika dalam kehidupan sehari-hari, bekerja sama dalam menyelesaikan masalah, serta mengembangkan sikap teliti, disiplin, dan percaya diri. Buku ini mendukung pencapaian kompetensi pembelajaran sesuai dengan kurikulum yang berlaku.','2026-07-10 14:36:48','2026-08-09 22:50:51'),(11,1,'Pendidikan Jasmani, Olahraga, dan Kesehatan untuk SMP/MTs Kelas VII','Buku Pendidikan Jasmani, Olahraga, dan Kesehatan Kelas VII SMP/MTs membahas berbagai materi tentang aktivitas olahraga, kebugaran jasmani, keterampilan gerak, serta pola hidup sehat. Buku ini membantu siswa memahami pentingnya olahraga, menjaga kesehatan, dan menerapkan sikap disiplin serta sportivitas dalam kehidupan sehari-hari.',30,'Ebta Heri Susanto Muhaji','Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2024',3,1,'tersedia',NULL,'Buku PJOK Kelas VII SMP/MTs bertujuan mengembangkan kemampuan fisik, keterampilan olahraga, pengetahuan kesehatan, serta sikap positif melalui aktivitas jasmani. Materi disusun untuk meningkatkan kebugaran, kerja sama, tanggung jawab, dan penerapan pola hidup sehat bagi peserta didik','2026-07-10 15:29:47','2026-08-09 22:50:51'),(12,3,'Buku Bahasa dan Sastra Indonesia Kelas IX (SMP/MTs)','Saat ini, bahasa Indonesia telah menjadi sarana komunikasi yang sangat penting dalam kehidupan. Tanpa disadari bahwa ketika berkomunikasi, pada dasarnya kalian berkomunikasi dengan menggunakan teks, baik teks lisan maupun tulis. Buku ini disusun berdasarkan Peraturan Menteri Pendidikan dan Kebudayaan Republik Indonesia Nomor 24 Tahun 2016 tentang Kompetensi Inti dan Kompetensi Dasar Pelajaran Kurikulum 2013 pada Pendidikan Dasar dan Pendidikan Menengah. Berdasarkan Peraturan Menteri tersebut, mata pelajaran bahasa Indonesia mengangkat berbagai jenis teks sebagai media pembelajaran. Sebagai contoh adalah ketika kalian ingin menanggapi suatu fenomena, kalian dapat mengungkapkannya melalui teks tanggapan. Kegiatan belajar dalam buku ini dirancang agar kalian membiasakan diri untuk gemar membaca, me-ngamati, bertanya, mencoba, menyajikan, dan menalar. Dengan strategi tersebut, diharapkan kalian memiliki pengetahuan, keterampilan, dan sikap dalam melaksanakan kegiatan berbahasa yang dilatihkan. Semoga kalian semakin mencintai bahasa Indonesia sebagai wujud rasa syukur atas anugerah Tuhan yang tidak ternilai, yaitu keberadaan bahasa Indonesia.',39,'Endah Tri Priyatni, M. Thamrin, Hadi Wardoyo','Bumi Aksara','2019',3,0,'tersedia',NULL,'Buku Bahasa dan Sastra Indonesia SMP/MTs Kelas IX merupakan buku ajar yang dirancang sebagai panduan pembelajaran bahasa Indonesia bagi siswa kelas IX. Isi buku mengintegrasikan kompetensi pengetahuan, keterampilan, sikap, dan apresiasi sastra melalui pembelajaran berbasis teks. Setiap bab memuat tujuan pembelajaran, contoh teks, aktivitas analisis, latihan, dan proyek yang mendorong peserta didik berpikir kritis serta mampu berkomunikasi secara efektif dalam berbagai konteks kehidupan. Selain meningkatkan keterampilan berbahasa, buku ini juga menanamkan nilai karakter, literasi, dan budaya Indonesia sesuai tuntutan Kurikulum 2013.','2026-07-10 15:37:05','2026-08-09 22:50:51'),(13,2,'Pendidikan Pancasila untuk SMP/MTs Kelas VIII','Pendidikan Pancasila adalah bidang studi yang menanamkan nilai-nilai dasar, moral, dan kesadaran berbangsa guna membentuk karakter warga negara yang cerdas dan bertanggung jawab. Bidang ini mengkaji lima sila sebagai falsafah negara, ideologi nasional, dan pandangan hidup bangsa Indonesia dalam menghadapi tantangan zaman.',40,'Tudi Setiawan Tia Setiawati Muhammad Sapei Prayogo','Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2023',3,0,'tersedia',NULL,'Buku Pendidikan Pancasila Kelas VIII SMP/MTs disusun sebagai sumber belajar yang bertujuan mengembangkan pengetahuan, sikap, dan keterampilan peserta didik dalam memahami serta mengamalkan nilai-nilai Pancasila sebagai dasar negara, ideologi bangsa, dan pedoman hidup berbangsa dan bernegara. Materi dalam buku membahas kedudukan dan fungsi Pancasila, norma dalam kehidupan bermasyarakat, hak dan kewajiban warga negara, semangat persatuan dalam keberagaman, serta pentingnya partisipasi aktif dalam kehidupan demokrasi sesuai dengan ketentuan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945. Pembelajaran disajikan melalui berbagai aktivitas, seperti diskusi, studi kasus, refleksi, dan proyek, yang mendorong peserta didik berpikir kritis, mampu memecahkan masalah, serta menunjukkan sikap bertanggung jawab dan menghargai keberagaman. Dengan demikian, buku ini diharapkan dapat membentuk peserta didik yang berkarakter Pancasila, menjunjung tinggi nilai-nilai kebangsaan, memiliki kepedulian sosial, serta mampu menerapkan prinsip-prinsip demokrasi dan kehidupan berbangsa dalam kehidupan sehari-hari.','2026-07-10 15:46:52','2026-08-09 22:50:51'),(14,1,'perahu kertas','Perahu Kertas mengisahkan pasang surut hubungan dua remaja, Kugy dan Keenan, yang sama-sama memiliki idealisme tinggi namun terbentang oleh realitas kehidupan.',9,'Dewi Lestari','Bentang Pustaka','2009',4,0,'tersedia',NULL,NULL,'2026-07-10 16:11:49','2026-08-04 04:52:13'),(17,1,'Bahasa dan Sastra Indonesia SMP/MTs Kelas VII (Edisi Revisi)','Saat ini, bahasa Indonesia telah menjadi sarana komunikasi yang sangat penting dalam kehidupan. Tanpa disadari bahwa ketika berkomunikasi, pada dasarnya kalian berkomunikasi dengan menggunakan teks, baik teks lisan maupun tulis. Buku ini disusun berdasarkan Peraturan Menteri Pendidikan dan Kebudayaan Republik Indonesia Nomor 24 Tahun 2016 tentang Kompetensi Inti dan Kompetensi Dasar Pelajaran pada Kurikulum 2013 pada Pendidikan Dasar dan Pendidikan Menengah. Berdasarkan Peraturan Menteri tersebut, mata pelajaran bahasa Indonesia mengangkat berbagai jenis teks sebagai media pembelajaran. Sebagai contoh adalah ketika kalian ingin mencari kesepakatan dengan pihak lain, kalian dapat mengungkapkannya dalam bentuk teks negosiasi. Kegiatan belajar dalam buku ini dirancang agar kalian membiasakan diri untuk gemar membaca, mengamati, bertanya, mencoba, menyajikan, dan menalar. Dengan strategi tersebut diharapkan kalian memiliki pengetahuan, keterampilan, dan sikap dalam melaksanakan kegiatan berbahasa yang dilatihkan. Semoga kalian semakin mencintai bahasa Indonesia sebagai wujud rasa syukur atas anugerah Tuhan yang tidak ternilai, yaitu keberadaan bahasa Indonesia',40,'Endah Tri Priyatni','Bumi Aksara','2019',3,1,'tersedia',NULL,'Buku Bahasa dan Sastra Indonesia Kelas VII SMP/MTs disusun sebagai bahan ajar yang bertujuan mengembangkan kemampuan berbahasa dan bersastra peserta didik secara terpadu. Materi dalam buku mencakup keterampilan menyimak, berbicara, membaca, dan menulis melalui pembelajaran berbasis teks. Siswa diajak mempelajari berbagai jenis teks, seperti teks deskripsi, cerita fantasi, prosedur, laporan hasil observasi, puisi rakyat, fabel, surat pribadi dan surat dinas, serta cara merangkum buku fiksi dan nonfiksi. Selain meningkatkan kompetensi berbahasa, buku ini juga menanamkan nilai karakter, kreativitas, kemampuan berpikir kritis, serta apresiasi terhadap karya sastra Indonesia. Penyajian materi dilakukan secara bertahap melalui contoh, latihan, diskusi, dan tugas proyek sehingga mendorong siswa aktif dalam proses pembelajaran. Dengan demikian, buku ini diharapkan mampu membentuk peserta didik yang memiliki kemampuan berkomunikasi secara efektif, berpikir logis, serta menghargai bahasa Indonesia sebagai bahasa persatuan dan identitas bangsa.','2026-07-22 05:31:53','2026-08-09 22:50:51'),(18,2,'Matematika untuk SMP/MTs Kelas VIII','Buku Matematika Kelas VII SMP/MTs berisi materi dasar matematika seperti bilangan, aljabar, persamaan, perbandingan, geometri, data, dan peluang. Buku ini disusun dengan contoh, latihan, dan kegiatan pembelajaran untuk membantu siswa memahami konsep matematika serta menerapkannya dalam kehidupan sehari-hari.',30,'Mohammad Tohir Abdur Rahman AsΓÇÖari Ahmad Choirul Anam Ibnu Tauiq','Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2022',3,0,'tersedia',NULL,'Buku Matematika Kelas VII SMP/MTs bertujuan mengembangkan kemampuan berpikir logis, kritis, dan kreatif melalui pembelajaran konsep-konsep matematika dasar. Materinya disajikan secara sistematis untuk meningkatkan pemahaman dan keterampilan siswa dalam menyelesaikan masalah matematika.','2026-07-22 06:02:25','2026-08-09 22:50:51'),(19,3,'Matematika untuk SMP/MTs Kelas IX','Buku Matematika Kelas IX SMP/MTs membahas materi seperti bilangan berpangkat, bentuk akar, persamaan dan fungsi kuadrat, transformasi geometri, bangun ruang, statistika, dan peluang. Buku ini membantu siswa memahami konsep matematika melalui contoh soal, latihan, dan penerapan dalam kehidupan sehari-hari.',30,'Yosep Dwi Kristanto Muhammad Taqiyuddin Elyda Yulfiana Indra Rukmana','Pusat Perbukuan Badan Standar, Kurikulum, dan Asesmen Pendidikan Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi Kompleks Kemdikbudristek','2022',3,0,'tersedia',NULL,'Buku Matematika Kelas IX SMP/MTs disusun untuk meningkatkan kemampuan berpikir logis, kritis, dan pemecahan masalah siswa melalui pembelajaran konsep matematika lanjutan. Materi disajikan secara sistematis agar siswa mampu memahami dan menerapkan matematika dalam berbagai situasi.','2026-07-22 06:09:51','2026-08-09 22:50:51'),(20,2,'Pendidikan Jasmani, Olahraga, dan Kesehatan untuk SMP/MTs Kelas VIII','Buku Pendidikan Jasmani, Olahraga, dan Kesehatan Kelas VIII SMP/MTs membahas materi tentang aktivitas olahraga, kebugaran jasmani, keterampilan gerak, dan kesehatan. Buku ini membantu siswa meningkatkan kemampuan fisik, memahami pola hidup sehat, serta menanamkan nilai disiplin, kerja sama, dan sportivitas.',30,'Yusnita Pusparagen Ebta Heri Susanto','Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2024',3,0,'tersedia',NULL,'Buku PJOK Kelas VIII SMP/MTs bertujuan mengembangkan kebugaran jasmani, keterampilan olahraga, pengetahuan kesehatan, serta sikap positif peserta didik melalui kegiatan fisik dan pembelajaran kesehatan. Buku ini mendukung siswa agar mampu menerapkan perilaku hidup sehat dalam kehidupan sehari-hari.','2026-07-22 06:22:08','2026-08-09 22:50:51'),(21,2,'Informatika untuk SMP/MTs Kelas VIII (Edisi Revisi)','Buku Informatika untuk SMP/MTs Kelas VIII (Edisi Revisi) membahas konsep informatika seperti sistem komputer, jaringan komputer, analisis data, algoritma, pemrograman, dan literasi digital. Buku ini membantu siswa memahami teknologi serta mengembangkan kemampuan berpikir kritis, kreatif, dan pemecahan masalah dalam dunia digital.',30,'Bambang Subeno Iman Budiman Des Erita Fenti','Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2024',3,0,'tersedia',NULL,'Buku Informatika untuk SMP/MTs Kelas VIII bertujuan meningkatkan kemampuan siswa dalam memahami dan memanfaatkan teknologi informasi melalui pembelajaran informatika. Materi disajikan secara sistematis dengan kegiatan praktik dan latihan untuk mengembangkan keterampilan digital, berpikir komputasional, kreativitas, serta tanggung jawab dalam penggunaan teknologi.','2026-07-22 06:38:28','2026-08-09 22:50:51'),(22,3,'Informatika untuk SMP/MTs Kelas IX (Edisi Revisi)','Buku Informatika untuk SMP/MTs Kelas IX (Edisi Revisi) membahas konsep informatika seperti berpikir komputasional, literasi digital, sistem komputer, data, algoritma, dan pemanfaatan teknologi. Buku ini membantu siswa memahami serta menggunakan teknologi secara kreatif, kritis, dan bertanggung jawab.',30,'Erlangga Erna Piantari Khairur Rosyidi','Kementerian Pendidikan Dasar dan Menengah','2025',3,0,'tersedia',NULL,'Buku Informatika untuk SMP/MTs Kelas IX bertujuan mengembangkan kemampuan siswa dalam memahami konsep informatika dan keterampilan digital melalui pembelajaran teori serta praktik. Materi disusun untuk melatih berpikir logis, pemecahan masalah, kreativitas, dan penggunaan teknologi secara bijak.','2026-07-22 06:44:09','2026-08-09 22:50:51'),(23,1,'Modul : Bahasa Indonesia Vll','Modul Bahasa Indonesia Kelas VII karya Akhmad Sukri berisi materi pembelajaran bahasa dan sastra Indonesia yang membantu siswa meningkatkan kemampuan membaca, menulis, berbicara, dan menyimak. Modul ini membahas berbagai jenis teks serta latihan untuk memahami dan menerapkan penggunaan bahasa Indonesia dengan baik dan benar.',30,'Akhmad Sukri, Sr Hallimas','dinas pendidikan olahraga dan pemuda gowa','2014',3,0,'tersedia',NULL,'Modul Bahasa Indonesia Kelas VII bertujuan mengembangkan kemampuan berbahasa siswa melalui pembelajaran teks, keterampilan komunikasi, dan apresiasi sastra. Materi disajikan secara sistematis dengan kegiatan belajar dan latihan agar siswa mampu berpikir kritis serta menggunakan bahasa Indonesia secara efektif.','2026-07-22 07:01:30','2026-07-22 07:01:30'),(24,2,'Modul : Bahasa Indonesia Vlll','Modul Bahasa Indonesia Kelas VIII berisi materi pembelajaran tentang berbagai jenis teks dan keterampilan berbahasa, seperti membaca, menulis, menyimak, dan berbicara. Modul ini membantu siswa memahami penggunaan bahasa Indonesia yang baik melalui kegiatan, contoh, latihan, dan tugas pembelajaran.',30,'Akhmad Sukri, St Hallimas','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul Bahasa Indonesia Kelas VIII bertujuan mengembangkan kemampuan berbahasa dan berpikir kritis siswa melalui pembelajaran teks serta aktivitas mandiri. Materi disajikan secara sistematis agar siswa mampu memahami, menganalisis, dan menghasilkan berbagai bentuk teks dengan menggunakan bahasa Indonesia secara efektif.','2026-07-22 07:07:23','2026-07-22 07:07:23'),(25,1,'English Shine ( Modul) Vll','Modul English Shine Kelas VII berisi materi pembelajaran bahasa Inggris yang membantu siswa meningkatkan kemampuan berkomunikasi dalam kehidupan sehari-hari. Modul ini mencakup kosakata, tata bahasa, teks sederhana, latihan membaca, menulis, berbicara, dan menyimak untuk mendukung keterampilan berbahasa Inggris siswa.',3,'H. jeauwa, A. Nuraqiah','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul English Shine Kelas VII bertujuan mengembangkan kemampuan bahasa Inggris siswa melalui pembelajaran yang komunikatif dan kontekstual. Materi disusun secara sistematis dengan berbagai kegiatan dan latihan agar siswa mampu memahami serta menggunakan bahasa Inggris dengan percaya diri dalam berbagai situasi.','2026-07-22 07:15:48','2026-07-24 13:57:35'),(26,2,'English Shine ( Modul) Vlll','Modul English Shine Kelas VIII berisi materi pembelajaran bahasa Inggris yang membantu siswa meningkatkan kemampuan berkomunikasi dalam berbagai situasi. Modul ini mencakup kosakata, tata bahasa, teks sederhana, serta latihan keterampilan listening, speaking, reading, dan writing agar siswa mampu menggunakan bahasa Inggris dengan baik.',4,'H. jeauwa, A. Nuraqiah','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul English Shine Kelas VIII bertujuan mengembangkan kemampuan berbahasa Inggris siswa melalui pembelajaran yang komunikatif dan kontekstual. Materi disajikan secara sistematis dengan berbagai aktivitas dan latihan untuk meningkatkan pemahaman bahasa, kreativitas, serta kepercayaan diri siswa dalam berkomunikasi menggunakan bahasa Inggris.','2026-07-22 07:19:00','2026-07-24 12:55:58'),(27,1,'Seni Budaya Vll Modul / Ganjil','Modul Seni Budaya Kelas VII Semester Ganjil berisi materi tentang berbagai bidang seni, seperti seni rupa, seni musik, seni tari, dan seni teater. Modul ini membantu siswa mengenal, memahami, serta mempraktikkan berbagai karya seni melalui kegiatan apresiasi dan kreativitas.',8,'Masmini ,Mpd, St suryani .Spd','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul Seni Budaya Kelas VII Semester Ganjil bertujuan mengembangkan kreativitas, keterampilan, dan apresiasi seni peserta didik. Materi disusun secara sistematis melalui teori, contoh karya, dan kegiatan praktik agar siswa mampu memahami serta mengekspresikan nilai seni dan budaya dalam kehidupan sehari-hari.','2026-07-22 07:29:17','2026-07-22 07:29:17'),(28,2,'Modul seni budaya Vlll / Ganjil','Modul Seni Budaya Kelas VIII Semester Ganjil berisi materi tentang seni rupa, seni musik, seni tari, dan seni teater yang bertujuan mengenalkan siswa pada berbagai bentuk karya seni dan budaya. Modul ini dilengkapi kegiatan apresiasi dan praktik untuk meningkatkan kreativitas serta kemampuan siswa dalam berkarya seni',4,'St. Suryani . Spd , Masmini . Mpd','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul Seni Budaya Kelas VIII Semester Ganjil disusun untuk mengembangkan pengetahuan, keterampilan, dan sikap apresiatif siswa terhadap seni dan budaya. Materi disajikan melalui pemahaman konsep, contoh karya, serta kegiatan praktik agar siswa mampu mengeksplorasi kreativitas dan menghargai keberagaman budaya Indonesia.','2026-07-22 07:33:44','2026-07-22 07:33:44'),(29,3,'Seni Budaya lX Modul / Ganjil','Modul Seni Budaya Kelas IX Semester Ganjil berisi materi tentang seni rupa, seni musik, seni tari, dan seni teater yang mengembangkan pemahaman serta keterampilan siswa dalam berkarya seni. Modul ini membantu siswa mengenal berbagai karya seni, melakukan apresiasi, dan mengekspresikan kreativitas melalui kegiatan praktik',4,'St. Suryani . Spd , Masmini . Mpd','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul Seni Budaya Kelas IX Semester Ganjil bertujuan meningkatkan kemampuan apresiasi, kreativitas, dan keterampilan seni peserta didik. Materi disusun secara sistematis melalui konsep, contoh karya, dan latihan praktik untuk membantu siswa memahami serta menerapkan nilai-nilai seni dan budaya dalam kehidupan sehari-hari.','2026-07-22 07:35:50','2026-07-22 07:35:50'),(30,1,'Modul SKTB IPA kelas Vll, Vlll, lX','Modul SKTB IPA Kelas VII, Vlll, lX berisi materi pembelajaran Ilmu Pengetahuan Alam yang mencakup konsep makhluk hidup, materi dan perubahannya, energi, sistem tubuh manusia, gaya, tekanan, gelombang, listrik, kemagnetan, pewarisan sifat, teknologi, serta lingkungan. Modul ini disusun untuk membantu siswa memahami berbagai fenomena alam melalui kegiatan pengamatan, percobaan, latihan, dan penerapan konsep IPA dalam kehidupan sehari-hari.',12,'Arfiani  Babay','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul SKTB IPA Kelas VII, Vlll, lX bertujuan mengembangkan pengetahuan, keterampilan ilmiah, dan kemampuan berpikir kritis peserta didik melalui pembelajaran IPA yang sistematis dan kontekstual. Materi disajikan melalui pemahaman konsep, kegiatan praktik, serta pemecahan masalah agar siswa mampu memahami fenomena alam dan menerapkan ilmu pengetahuan dalam kehidupan sehari-hari.','2026-07-22 08:00:50','2026-07-22 08:11:59'),(31,1,'Modul SKTB Matematika kelas Vll, Vlll, lX','Modul SKTB Matematika Kelas VII, VIII, dan IX berisi materi pembelajaran matematika yang mencakup bilangan, aljabar, persamaan dan fungsi, perbandingan, himpunan, geometri, bangun ruang, statistika, serta peluang. Modul ini disusun untuk membantu siswa memahami konsep matematika melalui contoh soal, latihan, dan penerapan dalam kehidupan sehari-hari.',8,'syafruddin .Spd Msi , Hj . Nurmi Spd','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul SKTB Matematika Kelas VII, VIII, dan IX bertujuan mengembangkan kemampuan berpikir logis, kritis, kreatif, dan sistematis peserta didik dalam memahami konsep serta menyelesaikan masalah matematika. Materi disajikan secara bertahap melalui penjelasan konsep, latihan, dan evaluasi untuk meningkatkan kemampuan numerasi serta penerapan matematika dalam berbagai situasi.8','2026-07-22 08:17:14','2026-07-22 08:17:14'),(32,1,'Modul SKTB IPS kelas Vll, Vlll, lX','Modul SKTB IPS Kelas VII, VIII, dan IX berisi materi Ilmu Pengetahuan Sosial yang mencakup geografi, sejarah, ekonomi, dan sosiologi. Modul ini membahas kehidupan masyarakat, interaksi sosial, kegiatan ekonomi, perkembangan sejarah Indonesia, serta hubungan manusia dengan lingkungan. Materi disajikan melalui contoh, latihan, dan kegiatan pembelajaran untuk membantu siswa memahami fenomena sosial dalam kehidupan sehari-hari.',12,'Surana, Hj. Suriati','Dikorda gowa','2014',3,0,'tersedia',NULL,'Modul SKTB IPS Kelas VII, VIII, dan IX bertujuan mengembangkan pemahaman peserta didik terhadap berbagai aspek kehidupan sosial, budaya, ekonomi, dan sejarah. Materi disusun secara sistematis untuk meningkatkan kemampuan berpikir kritis, analisis, serta kesadaran siswa terhadap lingkungan dan kehidupan bermasyarakat.','2026-07-22 08:19:06','2026-07-22 08:19:06'),(33,1,'Pendidikan Agama islam dan budi pekerti  Vll','Buku Pendidikan Agama Islam dan Budi Pekerti Kelas VII berisi materi tentang ajaran Islam yang mencakup Al-QurΓÇÖan dan Hadis, akidah, akhlak, fikih, serta sejarah kebudayaan Islam. Buku ini membantu siswa memahami nilai-nilai keislaman dan menerapkannya dalam kehidupan sehari-hari melalui sikap beriman, bertakwa, dan berakhlak mulia.',35,'Muhammad Ehsan','Kementerian Pendidikan dan Kebudayaan','2016',3,0,'tersedia',NULL,'Buku Pendidikan Agama Islam dan Budi Pekerti Kelas VII bertujuan mengembangkan pemahaman, penghayatan, dan pengamalan ajaran Islam serta pembentukan karakter peserta didik. Materi disajikan secara sistematis melalui kegiatan pembelajaran, contoh penerapan, dan latihan untuk membentuk sikap religius, disiplin, jujur, dan bertanggung jawab.','2026-07-22 08:25:55','2026-07-22 08:25:55'),(34,1,'prakarya SMP/MTs Kelas VII Buku Guru','Buku Guru Prakarya Kelas VII berisi panduan pembelajaran untuk membantu guru dalam mengajarkan materi Prakarya. Buku ini mencakup strategi pembelajaran, kegiatan praktik, penilaian, serta pengembangan kreativitas siswa melalui bidang kerajinan, rekayasa, budidaya, dan pengolahan',1,'Kementria Dan Kebudayan RI','Kementria Dan Kebudayan RI','2016',3,0,'tersedia',NULL,'Buku Guru Prakarya Kelas VII bertujuan memberikan pedoman bagi guru dalam merancang dan melaksanakan pembelajaran yang kreatif, aktif, dan berbasis keterampilan. Materi disusun untuk membantu siswa mengembangkan pengetahuan, keterampilan, sikap percaya diri, serta kemampuan menghasilkan karya dengan memanfaatkan sumber daya di lingkungan sekitar.','2026-07-22 08:32:02','2026-07-24 09:22:57'),(35,1,'Pendidikan Pancasila SMP/MTs Kelas VII Buku Guru','Buku Guru Pendidikan Pancasila Kelas VII merupakan panduan bagi pendidik dalam melaksanakan pembelajaran Pendidikan Pancasila berdasarkan Kurikulum Merdeka. Buku ini membantu guru merancang kegiatan pembelajaran, memahami capaian pembelajaran, menentukan strategi mengajar, serta melakukan asesmen terhadap peserta didik.',1,'Kementria Dan Kebudayaan RI','Kementria Dan Kebudayaan RI','2016',3,0,'tersedia',NULL,'Buku Panduan Guru Pendidikan Pancasila Kelas VII disusun sebagai pedoman dalam membantu guru mengembangkan pembelajaran yang aktif, kreatif, dan berpusat pada peserta didik. Buku ini memberikan arahan mengenai tujuan pembelajaran, langkah-langkah kegiatan pembelajaran, contoh aktivitas peserta didik, metode pembelajaran, asesmen, remedial, pengayaan, serta refleksi pembelajaran.\r\n\r\nMelalui buku ini, guru diarahkan untuk membangun peserta didik yang memiliki karakter sesuai Profil Pelajar Pancasila, yaitu beriman dan bertakwa kepada Tuhan Yang Maha Esa, berkebinekaan global, bergotong royong, mandiri, bernalar kritis, dan kreatif.','2026-07-22 08:34:51','2026-07-24 09:22:33'),(36,1,'pendidikan bahasa inggris SMP/MTs Kelas VII Buku Guru','Buku Guru English for Nusantara Kelas VII merupakan panduan bagi guru dalam melaksanakan pembelajaran Bahasa Inggris sesuai dengan prinsip Kurikulum Merdeka. Buku ini membantu guru memahami capaian pembelajaran Bahasa Inggris Fase D, menyusun kegiatan pembelajaran, memilih strategi mengajar, serta melakukan asesmen terhadap kemampuan peserta didik.',1,'Kementria Dan Kebudayaan RI','Kementria Dan Kebudayaan RI','2016',3,0,'tersedia',NULL,'Buku Panduan Guru Bahasa Inggris Kelas VII disusun sebagai pendamping guru dalam mengimplementasikan pembelajaran Bahasa Inggris yang berpusat pada peserta didik. Buku ini memuat panduan umum pembelajaran, karakteristik mata pelajaran Bahasa Inggris, capaian pembelajaran, tujuan pembelajaran, strategi pembelajaran, serta panduan khusus setiap unit pembelajaran.\r\n\r\nMelalui buku ini, guru diarahkan untuk menciptakan pembelajaran yang aktif, kreatif, dan kontekstual sehingga peserta didik mampu menggunakan Bahasa Inggris sebagai alat komunikasi dalam kehidupan sehari-hari. Selain itu, buku ini mendukung pengembangan karakter sesuai Profil Pelajar Pancasila melalui kegiatan kolaborasi, berpikir kritis, kreativitas, dan komunikasi.','2026-07-22 08:37:32','2026-07-24 09:21:49'),(37,1,'Legenda rawa pening ( Cerita rakyat dari jawa tengah )','Legenda Rawa Pening menceritakan kisah Baru Klinting, seorang anak sakti yang dihina dan diusir oleh penduduk desa. Hanya seorang nenek tua yang bersedia menolongnya. Setelah mencabut lidi yang ditancapkannya ke tanah, keluarlah air yang menenggelamkan desa hingga menjadi Rawa Pening. Cerita ini mengajarkan pentingnya berbuat baik dan tidak merendahkan orang lain.',10,'Tri Wahyuni','Badan Pengembangan dan Pembinaan Bahasa Jalan Daksinapati Barat IV  Rawamangun  Jakarta Timur','2016',4,1,'tersedia',NULL,'Legenda Rawa Pening merupakan cerita rakyat dari Jawa Tengah yang menjelaskan asal usul terbentuknya Rawa Pening. Cerita ini mengandung nilai moral tentang pentingnya kebaikan, kepedulian, kerendahan hati, serta larangan menghina atau memperlakukan orang lain dengan buruk.','2026-07-22 08:59:15','2026-08-09 22:50:51'),(38,1,'Putri  Nibung di sarang lanun','Putri Nibung di Sarang Lanun mengisahkan perjuangan Bujang Limpu menyelamatkan Putri Nibung yang diculik oleh para lanun (perompak laut). Dengan keberanian, kecerdikan, dan bantuan para sahabatnya, Bujang Limpu berhasil mengalahkan pemimpin lanun dan membawa Putri Nibung kembali. Mereka kemudian hidup bahagia bersama.',10,'Sarman','Badan Pengembangan dan Pembinaan Bahasa Jalan Daksinapati Barat IV Rawamangun Jakarta Timur','2016',4,0,'tersedia',NULL,'Putri Nibung di Sarang Lanun merupakan cerita rakyat dari Kepulauan Bangka Belitung yang mengangkat tema keberanian, cinta, dan perjuangan melawan kejahatan. Cerita ini mengajarkan nilai-nilai keberanian, ketekunan, kerja sama, dan keyakinan bahwa kebaikan akan mengalahkan kejahatan.','2026-07-22 09:11:13','2026-08-09 22:50:51'),(39,1,'ai Ngugha: Si Pemberani (Cerita Rakyat dari Lampung)','Sai Ngugha: Si Pemberani menceritakan perjuangan Sai Ngugha, seorang gadis pemberani dan baik hati yang bersama saudara-saudaranya menghadapi berbagai rintangan di hutan. Berkat keberanian, kecerdikan, dan ketulusan hatinya, ia berhasil mengatasi berbagai bahaya, bertemu kembali dengan orang-orang yang dicintainya, dan hidup bahagia.',10,'diah meutia harum','Badan Pengembangan dan Pembinaan Bahasa Jalan Daksinapati Barat IV Rawamangun Jakarta Timur','2016',4,0,'tersedia',NULL,'Sai Ngugha: Si Pemberani merupakan cerita rakyat dari Lampung yang mengangkat nilai keberanian, kepedulian, kerja keras, dan pantang menyerah. Cerita ini mengajarkan bahwa kebaikan, ketulusan, dan semangat untuk menolong sesama akan membawa kebahagiaan dan keberhasilan.','2026-07-22 09:24:10','2026-08-09 22:50:51'),(40,1,'Pak Abad pengobat tradisional','Pak Abad Pengobat Tradisional mengisahkan Pak Abad, seorang pengobat tradisional yang dikenal bijaksana, baik hati, dan selalu membantu masyarakat tanpa membeda-bedakan. Berkat pengetahuan, ketekunan, dan keikhlasannya dalam mengobati orang sakit, Pak Abad menjadi sosok yang dihormati dan membawa manfaat bagi banyak orang.',10,'Diyan kurniawati','Badan Pengembangan dan Pembinaan Bahasa Jalan Daksinapati Barat IV Rawamangun Jakarta Timur','2016',4,0,'tersedia',NULL,'Pak Abad Pengobat Tradisional merupakan cerita rakyat dari Kalimantan Timur yang mengangkat nilai kepedulian, keikhlasan, dan pengabdian kepada sesama. Cerita ini mengajarkan bahwa ilmu yang dimiliki hendaknya digunakan untuk menolong orang lain dengan tulus, sehingga memberikan manfaat bagi masyarakat.','2026-07-22 09:34:01','2026-08-09 22:50:51'),(41,1,'Pendidikan Pancasila dan Kewarganegaraan untuk SMP/MTs Kelas VII','Buku Pendidikan Pancasila dan Kewarganegaraan (PPKn) Kelas VII disusun untuk membantu peserta didik memahami nilai-nilai Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), dan Bhinneka Tunggal Ika. Materi disajikan secara sistematis melalui penjelasan konsep, kegiatan diskusi, studi kasus, latihan, dan proyek yang mendorong siswa berpikir kritis, memiliki sikap demokratis, serta mampu menerapkan nilai-nilai kewarganegaraan dalam kehidupan sehari-hari.',30,'Lukman Surya Saputra, Aa Nurdiaman, dan Salikun','Pusat Kurikulum dan Perbukuan, Badan Penelitian dan Pengembangan, Kementerian Pendidikan dan Kebudayaan Republik Indonesia.','2017',3,0,'tersedia',NULL,'Buku ini bertujuan membentuk peserta didik menjadi warga negara yang beriman, berkarakter Pancasila, bertanggung jawab, menghargai keberagaman, serta mampu berpartisipasi aktif dalam kehidupan bermasyarakat, berbangsa, dan bernegara. Materi pembelajaran mencakup empat pilar utama Pendidikan Kewarganegaraan, yaitu Pancasila, UUD Negara Republik Indonesia Tahun 1945, NKRI, dan Bhinneka Tunggal Ika, yang dipelajari melalui pendekatan ilmiah dan pembelajaran aktif.','2026-07-24 08:20:08','2026-08-09 22:50:51'),(42,2,'Pendidikan Pancasila dan Kewarganegaraan untuk SMP/MTs Kelas VI','Buku Pendidikan Pancasila dan Kewarganegaraan (PPKn) Kelas VIII disusun untuk membentuk peserta didik menjadi warga negara yang berkarakter Pancasila, demokratis, bertanggung jawab, dan menghargai keberagaman. Materi disajikan melalui penjelasan konsep, studi kasus, kegiatan diskusi, proyek, serta latihan yang mendorong peserta didik berpikir kritis dan menerapkan nilai-nilai Pancasila dalam kehidupan sehari-hari. Pembelajaran menggunakan pendekatan ilmiah (scientific approach) sesuai Kurikulum 2013',30,'Lukman Surya Saputra, Ida Rohayani, dan Salikun','Pusat Kurikulum dan Perbukuan, Balitbang, Kemendikbud','2017',3,0,'tersedia',NULL,'Buku ini membahas empat pilar utama Pendidikan Kewarganegaraan, yaitu Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), dan Bhinneka Tunggal Ika. Melalui berbagai aktivitas pembelajaran, peserta didik diarahkan untuk memahami hak dan kewajiban sebagai warga negara, menumbuhkan sikap cinta tanah air, menghargai keberagaman, serta berpartisipasi aktif dalam kehidupan bermasyarakat, berbangsa, dan bernegara.','2026-07-24 08:28:53','2026-08-09 22:50:51'),(43,3,'Pendidikan Pancasila dan Kewarganegaraan untuk SMP/MTs Kelas IX','Buku Pendidikan Pancasila dan Kewarganegaraan Kelas IX membahas nilai-nilai Pancasila, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Negara Kesatuan Republik Indonesia (NKRI), dan Bhinneka Tunggal Ika sebagai dasar kehidupan berbangsa dan bernegara. Materi disajikan melalui penjelasan konsep, studi kasus, diskusi, proyek, dan latihan yang mendorong peserta didik berpikir kritis, demokratis, serta bertanggung jawab sebagai warga negara',30,'Ai Tin Sumartini dan Asep Sutisna Putra.','Pusat Kurikulum dan Perbukuan, Balitbang, Kementerian Pendidikan dan Kebudayaan Republik Indonesia.','2018',3,0,'tersedia',NULL,'Buku ini bertujuan membentuk peserta didik menjadi warga negara yang berkarakter Pancasila, cinta tanah air, menghargai keberagaman, memahami hak dan kewajiban sebagai warga negara, serta mampu berpartisipasi aktif dalam kehidupan bermasyarakat, berbangsa, dan bernegara. Pembelajaran dikembangkan sesuai Kurikulum 2013 melalui pendekatan ilmiah yang aktif dan kontekstual.','2026-07-24 08:33:18','2026-08-09 22:50:51'),(44,1,'Lipi Poleng Tanah Lot ( cerita rakyat dari bali )','Lipi Poleng Tanah Lot merupakan cerita rakyat dari Bali yang mengisahkan perjalanan suci seorang brahmana bernama Dang Hyang Nirarta. Dalam pengembaraannya menyebarkan ajaran kebaikan dan spiritualitas, Nirarta tiba di kawasan pesisir Tanah Lot. Di tempat tersebut ia bersemedi untuk memohon petunjuk kepada Tuhan. Ketika kesucian tempat semedinya diganggu oleh makhluk halus, ia melepaskan sabuk bercorak hitam putih (poleng) yang dikenakannya. Dengan kesaktiannya, sabuk tersebut berubah menjadi Lipi Poleng, yaitu ular suci yang dipercaya menjaga kesucian kawasan Pura Luhur Tanah Lot.',5,'I Nyoman Argawa','Badan Pengembangan dan Pembinaan Bahasa, Kementerian Pendidikan dan Kebudayaan Republik Indonesia','2016',4,0,'tersedia',NULL,'Buku Lipi Poleng Tanah Lot mengangkat legenda asal-usul keberadaan ular suci Lipi Poleng di kawasan Pura Luhur Tanah Lot, Bali. Melalui kisah perjalanan Dang Hyang Nirarta, pembaca diperkenalkan pada nilai-nilai religius, budaya, dan kearifan lokal masyarakat Bali. Cerita ini menekankan pentingnya menjaga kesucian tempat ibadah, hidup selaras dengan alam, menghormati tradisi, serta memelihara persatuan dan kedamaian. Sebagai cerita rakyat, buku ini juga berperan dalam melestarikan warisan budaya Bali dan menanamkan pendidikan karakter kepada generasi muda.','2026-07-24 08:55:02','2026-08-09 22:50:51'),(45,1,'Cikal: Cerita Rakyat dari Daerah Istimewa Yogyakarta','Cerita Cikal mengisahkan asal-usul sebuah daerah di Daerah Istimewa Yogyakarta yang berkaitan dengan kehidupan masyarakat, perjuangan, dan nilai-nilai budaya setempat. Tokoh dalam cerita menghadapi berbagai peristiwa yang mengajarkan keberanian, kerja keras, serta pentingnya menjaga hubungan baik dengan sesama dan lingkungan.',5,'Dhanu Priyo Prabowo','Dhanu Priyo Prabowo','2016',4,0,'tersedia',NULL,'Cikal merupakan cerita rakyat dari Yogyakarta yang mengangkat nilai budaya dan kearifan lokal masyarakat Jawa. Cerita ini menggambarkan kehidupan masyarakat masa lalu dengan pesan moral tentang keteguhan hati, kebersamaan, tanggung jawab, dan penghargaan terhadap warisan budaya daerah.','2026-07-24 09:00:42','2026-08-09 22:50:51'),(46,1,'Si Kerongo: Cerita Rakyat dari Kalimantan Timur','Si Kerongo menceritakan kehidupan seorang anak bernama Kerongo yang memiliki keterbatasan dalam berpikir, tetapi disayangi oleh ibunya. Mereka hidup sederhana setelah ayah Kerongo meninggal. Dalam perjalanan hidupnya, Kerongo menghadapi berbagai tantangan dan berhadapan dengan Raja Belau, sosok yang memiliki sifat rakus dan kejam. Cerita ini menggambarkan kasih sayang keluarga, keberanian, dan kebaikan hati dalam menghadapi kesulitan.',5,'Aquari Mustikawati','Badan Pengembangan dan Pembinaan Bahasa, Jakarta Timur','2016',4,0,'tersedia',NULL,'Buku Si Kerongo merupakan cerita rakyat dari Kalimantan Timur yang mengandung nilai moral tentang kasih sayang, kesabaran, keberanian, dan ketulusan. Melalui kisah Kerongo dan keluarganya, pembaca diajak memahami pentingnya kebaikan hati, kepedulian terhadap sesama, serta nilai-nilai budaya masyarakat Kalimantan Timur.','2026-07-24 09:04:47','2026-08-09 22:50:51'),(47,1,'Ilmu Pengetahuan Sosial (IPS) SMP/MTs Kelas VII Buku Guru','Buku Guru IPS Kelas VII merupakan panduan bagi guru dalam melaksanakan pembelajaran IPS di tingkat SMP. Buku ini berisi petunjuk pembelajaran, strategi mengajar, kegiatan siswa, penilaian, serta cara mengembangkan materi IPS yang mencakup geografi, sejarah, ekonomi, dan sosiologi.',1,'Kementria Pendidikan Dan Kebudayaan RI','Kementria Pendidikan Dan Kebudayaan RI','2016',3,0,'tersedia',NULL,'Buku ini disusun untuk membantu guru memahami dan menerapkan pembelajaran IPS secara efektif. Materi IPS mengintegrasikan kajian tentang manusia, ruang, waktu, lingkungan, serta interaksi sosial dan ekonomi agar peserta didik mampu memahami kehidupan masyarakat dan mengembangkan sikap sosial yang baik.','2026-07-24 09:21:00','2026-07-24 09:21:00'),(48,1,'Bahasa Indonesia SMP/MTs Kelas VII Buku Guru','Buku Bahasa Indonesia Kelas VII Buku Guru merupakan pedoman bagi guru dalam melaksanakan pembelajaran Bahasa Indonesia di SMP/MTs. Buku ini berisi petunjuk mengajar, langkah pembelajaran, kegiatan siswa, penilaian, serta strategi memahami berbagai materi bahasa dan sastra Indonesia.',1,'Kementria Pendidikan Dan Kebudayaan RI','Kementria Pendidikan Dan Kebudayaan RI','2016',3,0,'tersedia',NULL,'Buku ini disusun untuk membantu guru mencapai tujuan pembelajaran Bahasa Indonesia melalui pendekatan yang aktif dan kontekstual. Isi buku mencakup panduan pembelajaran berbasis teks, pengembangan keterampilan membaca, menulis, berbicara, dan menyimak, serta cara melakukan penilaian terhadap kemampuan peserta didik','2026-07-24 09:25:55','2026-07-24 09:25:55'),(49,3,'Bahasa Indonesia SMP/MTs Kelas IX','Buku Bahasa Indonesia Kelas IX Buku Siswa berisi materi pembelajaran Bahasa Indonesia untuk siswa SMP/MTs kelas IX. Buku ini membimbing siswa memahami berbagai jenis teks, meningkatkan kemampuan membaca, menulis, berbicara, dan menyimak melalui kegiatan pembelajaran yang aktif dan kontekstual.',64,'Agus Trianto, Titik Harsiati, dan E. Kosasih','Kementerian Pendidikan dan Kebudayaan Republik Indonesia','2018',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan kemampuan berbahasa dan berpikir kritis peserta didik melalui pembelajaran berbasis teks. Materinya mencakup berbagai teks seperti teks laporan percobaan, pidato persuasif, cerpen, tanggapan, diskusi, dan karya sastra yang bertujuan meningkatkan keterampilan komunikasi siswa.','2026-07-24 09:36:14','2026-08-09 22:50:51'),(50,3,'Ilmu Pengetahuan Sosial (IPS) SMP/MTs Kelas IX','Buku IPS Kelas IX Revisi 2018 membahas berbagai aspek kehidupan masyarakat melalui kajian geografi, sejarah, ekonomi, dan sosiologi. Buku ini membantu siswa memahami perubahan sosial, perkembangan ekonomi, interaksi antarwilayah, serta peristiwa sejarah Indonesia dan dunia melalui kegiatan belajar, diskusi, dan latihan.',40,'Kementria Pendidikan Dan Kebudayaan RI','Kementria Pendidikan Dan Kebudayaan RI','2016',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan pemahaman peserta didik tentang kehidupan manusia dalam ruang dan waktu. Melalui pembelajaran IPS terpadu, siswa diarahkan untuk memiliki pengetahuan sosial, sikap peduli terhadap lingkungan dan masyarakat, serta kemampuan berpikir kritis dalam menghadapi berbagai masalah sosial.','2026-07-24 09:40:12','2026-08-09 22:50:51'),(51,1,'Pappilajarang Basa Mangkasarak SMP/MTs Kelas VII','Buku Pappilajarang Basa Mangkasarak merupakan buku pembelajaran Bahasa Makassar yang bertujuan mengenalkan peserta didik terhadap bahasa, sastra, dan budaya Makassar. Buku ini berisi materi tentang penggunaan bahasa Makassar dalam kehidupan sehari-hari, kosakata, percakapan, aksara Lontara, karya sastra daerah, serta berbagai nilai budaya masyarakat Makassar.\r\n\r\nMelalui buku ini, siswa diarahkan untuk mampu berkomunikasi menggunakan Bahasa Makassar sekaligus memahami dan menjaga warisan budaya daerah.',50,'Dr. Hj. Kembong Daeng, M.Hum.','CV. Indo Global Makassa','2022',3,0,'tersedia',NULL,'Pappilajarang Basa Mangkasarak membahas pembelajaran bahasa daerah Makassar yang mencakup aspek kebahasaan, kesastraan, dan kebudayaan. Buku ini disusun sebagai sumber belajar untuk meningkatkan kemampuan membaca, menulis, berbicara, dan memahami Bahasa Makassar. Selain itu, buku ini berperan dalam menanamkan kecintaan terhadap budaya lokal serta melestarikan bahasa daerah sebagai identitas masyarakat Makassar.','2026-07-31 10:04:00','2026-08-09 22:50:51'),(52,2,'Bahasa Mangkasarak (Bahasa Makassar) Kelas VIII SMP/MTs','uku Pappilajarang Basa Mangkasarak Kelas VIII merupakan buku pembelajaran bahasa daerah yang berisi materi bahasa, sastra, dan budaya Makassar. Buku ini membantu siswa memahami kosakata, tata bahasa, aksara Lontara, cerita, serta nilai budaya masyarakat Makassar agar mampu menggunakan dan melestarikan bahasa daerah.',50,'r. Hj. Kembong Daeng, M.Hum.','CV. Indo Global Makassar','2022',3,0,'tersedia',NULL,'Buku ini membahas pembelajaran Bahasa Makassar yang mencakup keterampilan berbahasa, sastra daerah, dan budaya lokal. Tujuannya adalah meningkatkan kemampuan siswa dalam membaca, menulis, berbicara, serta memahami budaya Makassar sebagai bagian dari identitas daerah.','2026-07-31 10:09:14','2026-07-31 10:09:14'),(53,3,'Pappilajarang Basa Mangkasarak SMP/MTs Kelas IX','Buku Pappilajarang Basa Mangkasarak Kelas IX merupakan buku pembelajaran Bahasa Makassar yang berisi materi bahasa, sastra, dan budaya daerah Makassar. Buku ini membantu siswa memahami penggunaan Bahasa Makassar, aksara Lontara, karya sastra, serta nilai budaya masyarakat Makassar dalam kehidupan sehari-hari.',50,'Dr. Hj. Kembong Daeng, M.Hum.','CV. Indo Global Makassar','2022',3,0,'tersedia',NULL,'Buku ini disusun untuk meningkatkan kemampuan siswa dalam berbahasa, bersastra, dan memahami budaya Makassar. Materinya mencakup keterampilan membaca, menulis, berbicara, serta pelestarian bahasa daerah sebagai identitas budaya.','2026-07-31 10:13:52','2026-08-09 22:50:51'),(54,1,'Pendidikan Pancasila dan Kewarganegaraan (PPKn) SMP/MTs Kelas VII','Buku PPKn Kelas VII membahas dasar-dasar kehidupan berbangsa dan bernegara, seperti nilai-nilai Pancasila, norma dalam masyarakat, Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, keberagaman bangsa Indonesia, serta pentingnya menjaga persatuan dan kesatuan. Buku ini bertujuan membentuk peserta didik menjadi warga negara yang bertanggung jawab.',12,'Lukman Surya Saputra, Aa Nurdiaman, dan Salikun','Pusat Kurikulum dan Perbukuan, Balitbang, Kementerian Pendidikan dan Kebudayaan Republik Indonesia','2017',3,0,'tersedia',NULL,'Buku ini menyajikan materi Pendidikan Pancasila dan Kewarganegaraan yang mencakup Pancasila, UUD 1945, Negara Kesatuan Republik Indonesia (NKRI), dan Bhinneka Tunggal Ika. Pembelajaran dalam buku ini diarahkan untuk membangun sikap cinta tanah air, berkarakter, dan memiliki kesadaran sebagai warga negara Indonesia.','2026-07-31 10:21:51','2026-08-09 22:50:51'),(55,2,'Pendidikan Pancasila dan Kewarganegaraan (PPKn) SMP/MTs Kelas VIII','Buku PPKn Kelas VIII membahas nilai-nilai Pancasila, konstitusi, hukum, demokrasi, keberagaman bangsa Indonesia, serta peran warga negara dalam menjaga persatuan dan kesatuan. Buku ini membantu siswa memahami hak dan kewajiban sebagai warga negara yang bertanggung jawab.',12,'Lukman Surya Saputra, Ida Rohayani, dan Salikun','Pusat Kurikulum dan Perbukuan, Balitbang, Kementerian Pendidikan dan Kebudayaan Republik Indonesia','2017',3,0,'tersedia',NULL,'Buku ini berisi materi Pendidikan Pancasila dan Kewarganegaraan yang bertujuan membentuk peserta didik menjadi warga negara yang berkarakter, berakhlak mulia, dan memiliki kesadaran terhadap kehidupan bermasyarakat, berbangsa, dan bernegara berdasarkan Pancasila dan UUD 1945.','2026-07-31 10:24:28','2026-08-09 22:50:51'),(56,3,'Pendidikan Pancasila dan Kewarganegaraan (PPKn) SMP/MTs Kelas IX','Buku PPKn Kelas IX membahas materi tentang nilai-nilai Pancasila, konstitusi negara, hak dan kewajiban warga negara, keberagaman masyarakat Indonesia, serta peran warga negara dalam menjaga persatuan dan kesatuan bangsa. Buku ini membantu siswa memahami kehidupan berbangsa dan bernegara berdasarkan Pancasila dan UUD 1945.',12,'Ai Tin Sumartini dan Asep Sutisna Putra.','Pusat Kurikulum dan Perbukuan, Balitbang, Kementerian Pendidikan dan Kebudayaan Republik Indonesia','2018',3,0,'tersedia',NULL,'Buku ini menyajikan pembelajaran Pendidikan Pancasila dan Kewarganegaraan yang bertujuan membentuk peserta didik menjadi warga negara yang berkarakter, bertanggung jawab, dan memiliki kesadaran hukum serta demokrasi. Materi dalam buku mencakup Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika sebagai dasar kehidupan masyarakat Indonesia.','2026-07-31 10:26:25','2026-08-09 22:50:51'),(57,1,'ahasa Inggris: When English Rings a Bell SMP/MTs Kelas VII','Buku Bahasa Inggris When English Rings a Bell Kelas VII merupakan buku pembelajaran yang membantu siswa mengembangkan kemampuan berbahasa Inggris melalui kegiatan membaca, menulis, berbicara, dan mendengarkan. Materinya disajikan melalui berbagai teks dan percakapan yang berkaitan dengan kehidupan sehari-hari.',54,'agus dasi priyanto','PT Tiga serangkai','2019',3,0,'tersedia',NULL,'uku ini disusun untuk meningkatkan kemampuan komunikasi bahasa Inggris siswa dengan pendekatan berbasis teks. Pembelajaran mencakup pemahaman kosakata, tata bahasa, serta penggunaan bahasa Inggris dalam konteks nyata agar siswa mampu menyampaikan informasi, gagasan, dan perasaan dengan baik.','2026-07-31 10:31:41','2026-08-09 22:50:51'),(58,2,'Bahasa Inggris: When English Rings a Bell SMP/MTs Kelas VIII','Buku Bahasa Inggris When English Rings a Bell Kelas VIII merupakan buku pembelajaran yang membantu siswa meningkatkan kemampuan berkomunikasi dalam bahasa Inggris. Materinya mencakup percakapan, teks pendek, kosakata, tata bahasa, serta kegiatan mendengarkan, berbicara, membaca, dan menulis dalam konteks kehidupan sehari-hari.',54,'agus dasi priyanto','PT Tiga serangkai','2019',3,0,'tersedia',NULL,'Buku ini disusun dengan pendekatan berbasis teks untuk mengembangkan kemampuan siswa dalam memahami dan menggunakan bahasa Inggris secara komunikatif. Pembelajaran diarahkan agar siswa mampu menyampaikan informasi, gagasan, dan perasaan melalui berbagai bentuk teks lisan maupun tulisan.','2026-07-31 10:34:32','2026-08-09 22:50:51'),(59,1,'Bahasa Inggris: When English Rings a Bell SMP/MTs Kelas IX','uku Bahasa Inggris When English Rings a Bell Kelas IX merupakan buku pembelajaran yang membantu siswa meningkatkan kemampuan berbahasa Inggris melalui kegiatan membaca, menulis, berbicara, dan mendengarkan. Materi disusun menggunakan berbagai teks dan percakapan yang berkaitan dengan kehidupan sehari-hari serta komunikasi global.',10,'agus dasi priyanto','PT Tiga serangkai','2019',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan kemampuan komunikasi bahasa Inggris siswa melalui pendekatan berbasis teks. Materinya mencakup pemahaman kosakata, tata bahasa, serta penggunaan bahasa Inggris dalam berbagai situasi agar siswa mampu menyampaikan informasi, ide, dan perasaan secara efektif.','2026-07-31 10:39:44','2026-07-31 10:39:44'),(60,3,'Informatika untuk SMA/MA Kelas lX (Kurikulum Merdeka)','Buku Informatika untuk SMA/MA Kelas X Kurikulum Merdeka membahas dasar-dasar ilmu informatika, seperti berpikir komputasional, teknologi informasi, sistem komputer, jaringan komputer, algoritma, pemrograman, serta dampak sosial teknologi. Buku ini dilengkapi kegiatan pembelajaran untuk membantu siswa memahami penerapan informatika dalam kehidupan sehari-hari.',3,'rudy setiawan,desi surningsih,penerbit mectiatama','Pusat Kurikulum dan Perbukuan','2024',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan kemampuan berpikir logis, kreatif, dan kritis melalui pembelajaran informatika. Materinya bertujuan membekali siswa dengan keterampilan digital, pemahaman teknologi, serta kemampuan memecahkan masalah menggunakan konsep informatika sesuai tuntutan era digital.','2026-07-31 10:48:28','2026-08-09 22:50:51'),(61,3,'Seni Budaya SMP/MTs Kelas IX','Buku Seni Budaya Kelas IX berisi pembelajaran tentang berbagai bidang seni, yaitu seni rupa, seni musik, seni tari, dan seni teater. Buku ini mengajak siswa mengenal, mengapresiasi, serta menciptakan karya seni melalui kegiatan praktik dan pemahaman budaya Indonesia.',3,'aditya hadiprayitno,annisa nur rahman','mediatama','2024',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan pengetahuan, keterampilan, dan sikap apresiasi siswa terhadap seni budaya. Materinya mencakup pemahaman karya seni, proses berkarya, serta nilai budaya yang terkandung dalam berbagai bentuk seni.','2026-07-31 11:24:09','2026-08-09 22:50:51'),(62,3,'English for Nusantara untuk SMP/MTs Kelas IX (kumer)','Buku English for Nusantara Kelas IX merupakan buku pembelajaran Bahasa Inggris yang mengangkat berbagai tema kehidupan, budaya, dan lingkungan sekitar. Buku ini membantu siswa mengembangkan kemampuan membaca, menulis, berbicara, dan menyimak melalui berbagai jenis teks seperti naratif, deskriptif, prosedur, dan teks informasi.',60,'silfana asr susanti, risky gurwindari','mediatama','2024',3,0,'tersedia',NULL,'Buku ini disusun untuk meningkatkan kemampuan komunikasi Bahasa Inggris siswa sesuai Kurikulum Merdeka. Materinya menekankan keterampilan berbahasa, berpikir kritis, kreativitas, serta pemahaman budaya melalui kegiatan pembelajaran berbasis teks dan aktivitas kontekstual','2026-07-31 11:27:48','2026-07-31 11:27:48'),(63,3,'Pendidikan Jasmani, Olahraga, dan Kesehatan (PJOK) untuk SMP/MTs Kelas IX ΓÇô Kurikulum Merdeka','Buku PJOK Kelas IX Kurikulum Merdeka membahas berbagai materi tentang aktivitas jasmani, olahraga, kebugaran tubuh, kesehatan, serta pola hidup sehat. Buku ini membantu siswa memahami teknik olahraga, meningkatkan keterampilan gerak, menjaga kesehatan, dan membangun sikap disiplin serta sportivitas.',20,'khairuddin,erika putri nur utama','mediatama','2024',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan kemampuan fisik, pengetahuan olahraga, keterampilan gerak, dan kesadaran hidup sehat peserta didik. Pembelajaran PJOK tidak hanya berfokus pada aktivitas olahraga, tetapi juga membentuk karakter, kebugaran jasmani, dan perilaku hidup sehat.','2026-07-31 11:32:52','2026-08-09 22:50:51'),(64,1,'Hutan','Buku Hutan membahas berbagai jenis hutan di dunia, kehidupan tumbuhan dan hewan yang ada di dalamnya, serta peran penting hutan bagi keseimbangan alam. Buku ini mengenalkan ekosistem hutan dengan bahasa sederhana dan dilengkapi ilustrasi menarik untuk anak-anak.',10,'L. Colvin dan E. Speare','PT Gading Inti Prima','2009',3,0,'tersedia',NULL,'Buku ini merupakan ensiklopedia pengetahuan alam yang memberikan informasi tentang hutan, keanekaragaman hayati, serta hubungan antara makhluk hidup dan lingkungan. Buku ini bertujuan meningkatkan pemahaman pembaca tentang pentingnya menjaga kelestarian hutan.','2026-07-31 11:43:20','2026-07-31 11:43:20'),(65,1,'Mengenal Tokoh-Tokoh Pergerakan Nasional','Buku Mengenal Tokoh-Tokoh Pergerakan Nasional berisi kisah dan perjuangan tokoh-tokoh bangsa Indonesia dalam membangun kesadaran nasional menuju kemerdekaan. Buku ini mengenalkan peran para tokoh pergerakan melalui organisasi, pendidikan, dan perjuangan politik melawan penjajahan.',10,'enny sukasih','mediatama','2008',3,0,'tersedia',NULL,'Buku ini membahas tokoh-tokoh penting dalam sejarah pergerakan nasional Indonesia serta kontribusinya dalam memperjuangkan kemerdekaan. Melalui buku ini, pembaca dapat memahami nilai perjuangan, nasionalisme, dan semangat kebangsaan dari para tokoh Indonesia.','2026-07-31 11:45:54','2026-07-31 11:45:54'),(66,1,'Pupuk Kompos','Buku Pupuk Kompos membahas tentang pengertian, manfaat, bahan dasar, serta cara pembuatan pupuk kompos dari bahan organik seperti daun, rumput, jerami, dan limbah rumah tangga. Buku ini memberikan panduan praktis untuk menghasilkan kompos yang baik bagi tanaman dan lingkungan.',10,'latran habibi st','tetian ilmu','2008',3,0,'tersedia',NULL,'Buku ini menyajikan informasi mengenai pupuk kompos sebagai pupuk organik yang ramah lingkungan. Pembahasannya mencakup proses pengolahan bahan organik menjadi kompos serta manfaatnya dalam meningkatkan kesuburan tanah dan mendukung pertanian berkelanjutan.','2026-07-31 11:48:12','2026-07-31 11:48:12'),(67,1,'Membuat Aneka Pigura','Buku Membuat Aneka Pigura berisi panduan membuat berbagai macam pigura kreatif dengan memanfaatkan bahan sederhana dan barang bekas. Buku ini mengajarkan cara mengolah bahan menjadi kerajinan yang menarik, seperti pigura dari kain flanel, kerikil, sumpit, dan berbagai bahan lainnya.',10,'bagas shinugi','PT Mediantara Semesta, Jakarta','2010',3,0,'tersedia',NULL,'Buku ini membahas teknik pembuatan aneka pigura sebagai bentuk pengembangan kreativitas dan keterampilan tangan. Melalui langkah-langkah sederhana, pembaca dapat memanfaatkan barang bekas menjadi karya seni yang memiliki nilai estetika dan manfaat.','2026-07-31 11:53:47','2026-07-31 11:53:47'),(68,1,'Mengenal Piranti Komputer Pribadi','Buku Mengenal Piranti Komputer Pribadi membahas berbagai perangkat komputer pribadi (Personal Computer/PC), mulai dari perangkat keras seperti CPU, monitor, keyboard, mouse, hingga perangkat pendukung lainnya. Buku ini membantu pembaca mengenal fungsi dan cara kerja komponen komputer secara sederhana',10,'Abu Azka','Cahaya Pustaka Raga','2009',3,0,'tersedia',NULL,'Buku ini menyajikan pengetahuan dasar mengenai piranti komputer pribadi dan teknologi pendukungnya. Pembahasan mencakup pengenalan komponen komputer serta kegunaannya dalam kehidupan sehari-hari sehingga pembaca dapat memahami perkembangan dan pemanfaatan komputer.','2026-07-31 11:56:20','2026-07-31 11:56:20'),(69,1,'Kerajinan Keramik','Buku Kerajinan Keramik membahas tentang pengenalan keramik, bahan dasar tanah liat, alat yang digunakan, serta teknik pembuatan berbagai bentuk kerajinan keramik. Buku ini memberikan panduan sederhana bagi pembaca untuk memahami proses pembuatan karya keramik yang bernilai seni dan berguna.',10,'Surasdi, BA.','Kanisius, Yogyakarta','2009',3,0,'tersedia',NULL,'Buku ini berisi pengetahuan dan keterampilan mengenai pembuatan kerajinan keramik, mulai dari pemilihan bahan, pembentukan, hingga penyelesaian karya. Buku ini bertujuan mengembangkan kreativitas dan keterampilan tangan dalam menghasilkan produk kerajinan berbahan tanah liat.','2026-07-31 11:58:20','2026-07-31 11:58:20'),(70,1,'Aku Ingin Jadi Arsitek','Buku Aku Ingin Jadi Arsitek mengenalkan profesi arsitek kepada anak-anak. Buku ini menjelaskan tugas seorang arsitek dalam merancang dan membuat bangunan, serta memberikan motivasi agar anak mengenal cita-cita dan berusaha mengembangkan kemampuan untuk meraihnya.',10,'Tina dan Dini','globalindo','2009',3,0,'tersedia',NULL,'Buku ini berisi informasi tentang profesi arsitek, mulai dari pekerjaan, keterampilan yang dibutuhkan, hingga peran arsitek dalam menciptakan bangunan yang bermanfaat. Buku ini bertujuan menambah wawasan anak tentang berbagai pilihan cita-cita dan dunia kerja.','2026-07-31 12:01:17','2026-08-09 22:50:51'),(71,1,'Membuat Gula Semut','Buku Membuat Gula Semut membahas cara pembuatan gula semut dari bahan alami seperti nira kelapa atau gula aren. Buku ini menjelaskan bahan, alat, proses pengolahan, hingga teknik menghasilkan gula semut yang berkualitas dan memiliki nilai ekonomi.',10,'Suwardono','PT Sandiarta Sukses, Bandung','2009',3,0,'tersedia',NULL,'Buku ini menyajikan pengetahuan praktis tentang pengolahan gula semut sebagai produk pangan berbahan dasar gula aren/kelapa. Pembahasannya bertujuan memberikan keterampilan kepada pembaca dalam membuat produk olahan yang higienis, tahan lama, dan bernilai jual.','2026-07-31 12:02:39','2026-07-31 12:02:39'),(72,1,'Membuat Anyaman Tradisional','Buku Membuat Anyaman Tradisional membahas cara membuat berbagai kerajinan anyaman menggunakan bahan-bahan sederhana seperti bambu, rotan, pandan, dan bahan alami lainnya. Buku ini menjelaskan teknik dasar menganyam serta proses pembuatan benda kerajinan yang memiliki nilai seni dan manfaat dalam kehidupan sehari-hari',10,'hary triana','karya mandiri persedia','2007',3,0,'tersedia',NULL,'Buku ini berisi panduan keterampilan membuat anyaman tradisional, mulai dari pengenalan bahan, teknik menganyam, hingga menghasilkan berbagai bentuk kerajinan. Buku ini bertujuan mengembangkan kreativitas dan melestarikan budaya kerajinan tangan tradisional Indonesia.','2026-07-31 12:06:53','2026-07-31 12:06:53'),(73,1,'Berkreasi dengan Kulit Jagung','Buku Berkreasi dengan Kulit Jagung membahas cara memanfaatkan limbah kulit jagung menjadi berbagai kerajinan tangan yang menarik, seperti bunga hias dan berbagai bentuk karya kreatif lainnya. Buku ini memberikan panduan langkah demi langkah dalam mengolah kulit jagung menjadi karya bernilai seni.',10,'Retno Sulistyowati dan Ratna Koesoemaningsih','Puspa Swara, Jakarta','2002',3,0,'tersedia',NULL,'Buku ini berisi pengetahuan dan keterampilan tentang pemanfaatan kulit jagung sebagai bahan kerajinan. Melalui teknik sederhana dan kreatif, pembaca diajarkan mengolah limbah alam menjadi produk hias yang memiliki nilai estetika dan manfaat.','2026-07-31 12:10:11','2026-07-31 12:10:11'),(74,3,'Pendidikan Agama Islam dan Budi Pekerti untuk SMP/MTs Kelas IX (Kurikulum Merdeka)','Buku Pendidikan Agama Islam dan Budi Pekerti Kelas IX Kurikulum Merdeka membahas ajaran Islam yang meliputi Al-QurΓÇÖan dan Hadis, akidah, akhlak, fikih, serta sejarah peradaban Islam. Buku ini membantu peserta didik memahami nilai-nilai keislaman dan menerapkannya dalam kehidupan sehari-hari.',40,'Iis Suryatini dan Hasyim AsyΓÇÖari','Pusat Perbukuan, Badan Standar, Kurikulum, dan Asesmen Pendidikan (BSKAP), Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi bekerja sama dengan Kementerian Agama Republik Indonesia','2024',3,0,'tersedia',NULL,'Buku ini disusun untuk membentuk peserta didik yang beriman, bertakwa kepada Allah SWT, berakhlak mulia, serta memiliki pemahaman agama yang baik. Materi pembelajaran diarahkan untuk mengembangkan pengetahuan, sikap, dan keterampilan sesuai dengan nilai-nilai Islam dan Profil Pelajar Pancasila.','2026-07-31 12:14:21','2026-08-09 22:50:51'),(75,3,'Bahasa Indonesia untuk SMP/MTs Kelas IX (Kurikulum Merdeka)','Buku Bahasa Indonesia Kelas IX Kurikulum Merdeka berisi pembelajaran untuk meningkatkan kemampuan menyimak, membaca, berbicara, dan menulis. Materinya mencakup berbagai jenis teks seperti teks deskripsi, prosedur, eksplanasi, laporan, argumentasi, serta karya fiksi dan nonfiksi yang berkaitan dengan kehidupan sehari-hari.',40,'budi waluyo','pt tiga serangkai pustaka mandiri','2024',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan keterampilan berbahasa dan literasi peserta didik melalui kegiatan membaca, memahami, menganalisis, dan menghasilkan berbagai teks. Pembelajaran diarahkan agar siswa mampu berkomunikasi secara efektif, berpikir kritis, kreatif, serta menghargai karya bahasa dan sastra Indonesia.','2026-07-31 12:16:38','2026-07-31 12:16:38'),(76,3,'Ilmu Pengetahuan Alam untuk SMP/MTs Kelas IX (Kurikulum Merdeka)','Buku Ilmu Pengetahuan Alam Kelas IX Kurikulum Merdeka membahas konsep-konsep IPA secara terpadu, meliputi pertumbuhan dan perkembangan makhluk hidup, sistem koordinasi dan reproduksi manusia, tekanan, listrik dan magnet, reaksi kimia, pewarisan sifat, bioteknologi, serta isu-isu lingkungan. Materi disajikan melalui kegiatan pengamatan, eksperimen, dan pemecahan masalah sehingga membantu siswa memahami penerapan ilmu pengetahuan dalam kehidupan sehari-hari.',40,'Cece Sutia, Victoriani Inabuy, Okky Fajar Tri, Maryana Budiyanti, Dwi Hardanie, dan Sri Handayani Lestari.','Pusat Perbukuan, Badan Standar, Kurikulum, dan Asesmen Pendidikan (BSKAP), Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi Republik Indonesia.','2022',3,0,'tersedia',NULL,'Buku ini disusun untuk mengembangkan pengetahuan, keterampilan proses sains, berpikir kritis, dan kemampuan memecahkan masalah sesuai Kurikulum Merdeka. Pembelajaran mendorong peserta didik melakukan penyelidikan ilmiah, memahami fenomena alam, serta menumbuhkan kepedulian terhadap lingkungan dan perkembangan teknologi.','2026-07-31 12:19:12','2026-08-09 22:50:51'),(77,3,'Pendidikan Pancasila untuk SMP/MTs Kelas IX kurikulum Merdeka','Buku ini membahas nilai-nilai Pancasila sebagai dasar negara, hubungan Pancasila dengan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Bhinneka Tunggal Ika, Negara Kesatuan Republik Indonesia, serta hak, kewajiban, dan partisipasi warga negara. Materi disajikan melalui aktivitas, diskusi, dan proyek yang mendorong peserta didik berpikir kritis serta menerapkan nilai-nilai Pancasila dalam kehidupan sehari-hari.',40,'Yudha Dana Prahara, Khoiriyaningsih, dan Anggi Afriansyah.','Pusat Perbukuan, Badan Standar, Kurikulum, dan Asesmen Pendidikan (BSKAP), Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi Republik Indonesia.','2023',3,0,'tersedia',NULL,'Buku Pendidikan Pancasila Kelas IX Kurikulum Merdeka disusun sebagai buku teks utama untuk membantu peserta didik memahami nilai-nilai Pancasila, konstitusi, keberagaman, dan kehidupan demokratis. Materi pembelajaran dirancang untuk membentuk karakter pelajar yang beriman, berkebinekaan, bertanggung jawab, serta mampu berperan sebagai warga negara yang baik sesuai Profil Pelajar Pancasila.','2026-07-31 12:23:16','2026-08-09 22:50:51'),(78,1,'Sejarah Perkembangan Islam','Buku Sejarah Perkembangan Islam membahas perjalanan sejarah Islam sejak masa Nabi Muhammad saw., perkembangan dakwah pada masa Khulafaur Rasyidin, Dinasti Umayyah, Dinasti Abbasiyah, hingga penyebaran Islam ke berbagai wilayah dunia, termasuk Indonesia. Buku ini juga menjelaskan perkembangan ilmu pengetahuan, kebudayaan, dan peradaban Islam.',3,'Samsul Munir Amin','Amzah, Jakarta','2019',3,0,'tersedia',NULL,'Buku ini menyajikan uraian mengenai perkembangan agama dan peradaban Islam dari masa awal hingga era modern. Pembahasannya mencakup tokoh-tokoh penting, pemerintahan Islam, penyebaran dakwah, serta kontribusi Islam terhadap ilmu pengetahuan dan kebudayaan dunia. Buku ini bertujuan memberikan pemahaman yang komprehensif mengenai sejarah perkembangan Islam.','2026-07-31 12:26:18','2026-08-09 22:50:51'),(79,1,'Sejarah dan Peradaban Dunia','Buku Sejarah dan Peradaban Dunia membahas perjalanan sejarah berbagai peradaban besar di dunia, mulai dari Mesir Kuno, Mesopotamia, Yunani, Romawi, India, Tiongkok, hingga perkembangan peradaban modern. Buku ini menjelaskan bagaimana peradaban-peradaban tersebut berkembang dan memberikan pengaruh terhadap kehidupan manusia di berbagai bidang.',2,'M. C. Ricklefs','Penerbit Erlangga','2014',3,0,'tersedia',NULL,'Buku ini menyajikan kajian mengenai sejarah dan perkembangan peradaban dunia secara kronologis. Materinya mencakup aspek politik, ekonomi, sosial, budaya, ilmu pengetahuan, dan teknologi yang membentuk kemajuan peradaban manusia dari masa kuno hingga masa modern. Buku ini bertujuan memberikan wawasan tentang proses perkembangan masyarakat dunia dan pengaruhnya terhadap kehidupan saat ini.','2026-07-31 12:28:40','2026-07-31 12:28:40'),(80,1,'Masa Pemuda Putra Sang Fajar','Buku Masa Pemuda Putra Sang Fajar mengisahkan perjalanan masa muda salah satu tokoh besar Indonesia, mulai dari kehidupan keluarga, pendidikan, hingga tumbuhnya semangat nasionalisme. Buku ini menggambarkan bagaimana pengalaman hidup pada masa muda membentuk karakter kepemimpinan, kecintaan terhadap tanah air, dan perjuangan untuk kemerdekaan Indonesia.',3,'Muhammad Hatta','Yudhistira,','2004',3,0,'tersedia',NULL,'Buku ini menyajikan kisah biografi masa muda seorang tokoh nasional Indonesia yang berperan penting dalam perjuangan kemerdekaan. Pembahasannya menitikberatkan pada proses pembentukan karakter, pendidikan, dan nilai-nilai perjuangan yang menginspirasi generasi muda untuk mencintai bangsa dan negara.','2026-07-31 12:30:26','2026-07-31 12:30:26'),(81,1,'Tokoh-Tokoh Pengubah Dunia','Buku Tokoh-Tokoh Pengubah Dunia mengulas kisah hidup dan perjuangan berbagai tokoh yang memberikan pengaruh besar terhadap perkembangan dunia, seperti ilmuwan, pemimpin, penemu, dan tokoh kemanusiaan. Setiap kisah menjelaskan perjalanan hidup, prestasi, serta kontribusi mereka dalam mengubah sejarah dan kehidupan masyarakat.',2,'Tim Elex Media Komputindo','Elex Media Komputindo','2010',3,0,'tersedia',NULL,'Buku ini menyajikan biografi singkat tokoh-tokoh dunia yang berjasa dalam bidang ilmu pengetahuan, politik, teknologi, dan kemanusiaan. Tujuannya adalah memberikan wawasan serta inspirasi kepada pembaca mengenai nilai kerja keras, kepemimpinan, kreativitas, dan semangat untuk memberikan manfaat bagi masyarakat.','2026-07-31 12:32:47','2026-08-09 22:50:51'),(82,1,'Mengenal Makhluk Hidup','Buku Mengenal Makhluk Hidup mengenalkan berbagai jenis makhluk hidup, seperti manusia, hewan, tumbuhan, dan mikroorganisme. Buku ini menjelaskan ciri-ciri makhluk hidup, kebutuhan hidup, cara berkembang biak, serta hubungan makhluk hidup dengan lingkungannya menggunakan bahasa yang mudah dipahami dan dilengkapi ilustrasi.',2,'Tim Redaksi Tiga Serangkai','Tiga Serangkai Pustaka Mandiri,','2011',3,0,'tersedia',NULL,'Buku ini membahas konsep dasar makhluk hidup, meliputi pengertian, klasifikasi, ciri-ciri, serta interaksi makhluk hidup dengan lingkungan. Materi disusun untuk membantu pembaca memahami keanekaragaman hayati dan pentingnya menjaga keseimbangan ekosistem.','2026-07-31 12:35:17','2026-07-31 12:35:17'),(83,1,'Cakrawala Astronomi','uku Cakrawala Astronomi membahas pengetahuan tentang alam semesta, mulai dari tata surya, planet, bintang, galaksi, hingga berbagai fenomena langit. Buku ini membantu pembaca memahami perkembangan ilmu astronomi serta hubungan manusia dengan alam semesta melalui penjelasan yang mudah dipahami.',1,'Dedi Suard','Remaja Rosdakarya, Bandung','2003',3,0,'tersedia',NULL,'Buku ini menyajikan kajian dasar mengenai astronomi yang mencakup benda-benda langit, sistem tata surya, dan fenomena alam di luar bumi. Materi disusun untuk menambah wawasan pembaca tentang ruang angkasa serta perkembangan ilmu pengetahuan mengenai alam semesta.','2026-07-31 12:37:37','2026-07-31 12:37:37'),(84,1,'Pramuka Saka Bhayangkara','Buku Pramuka Saka Bhayangkara membahas tentang salah satu satuan karya dalam Gerakan Pramuka yang bekerja sama dengan bidang kepolisian. Buku ini menjelaskan sejarah, tujuan, kegiatan, krida, serta keterampilan yang dipelajari anggota Saka Bhayangkara dalam bidang keamanan, ketertiban masyarakat, dan kedisiplinan.',10,'Kwartir Nasional Gerakan Pramuka (Kwarnas)','Kwartir Nasional Gerakan Pramuka','2012',3,0,'tersedia',NULL,'Buku ini berisi pengetahuan dan pedoman mengenai Saka Bhayangkara sebagai wadah pembinaan generasi muda melalui kegiatan kepramukaan. Materinya mencakup nilai kedisiplinan, tanggung jawab, kerja sama, serta keterampilan yang mendukung pembentukan karakter dan kepedulian sosial.','2026-07-31 12:40:48','2026-08-09 22:50:51'),(85,1,'Nilai-Nilai Pancasila','Buku Nilai-Nilai Pancasila membahas makna dan kedudukan Pancasila sebagai dasar negara serta pandangan hidup bangsa Indonesia. Buku ini menjelaskan nilai-nilai yang terkandung dalam setiap sila Pancasila dan penerapannya dalam kehidupan bermasyarakat, berbangsa, dan bernegara.',10,'Kaelan','paradigma','2014',3,0,'tersedia',NULL,'Buku ini mengkaji nilai filosofis Pancasila sebagai landasan kehidupan bangsa Indonesia. Pembahasannya mencakup nilai ketuhanan, kemanusiaan, persatuan, kerakyatan, dan keadilan serta bagaimana nilai tersebut dapat diwujudkan dalam sikap dan perilaku warga negara.','2026-07-31 12:44:03','2026-08-09 22:50:51'),(86,1,'Psikologi Remaja','Buku Psikologi Remaja: Perkembangan Peserta Didik membahas perkembangan psikologis remaja, meliputi perubahan fisik, emosi, sosial, moral, intelektual, serta pembentukan identitas diri. Buku ini membantu memahami karakteristik dan permasalahan yang sering dialami remaja dalam proses menuju kedewasaan.',10,'Mohammad Ali dan Mohammad Asrori','PT Bumi Aksara,','2014',3,0,'tersedia',NULL,'Buku ini menyajikan kajian tentang perkembangan remaja dari sudut pandang psikologi pendidikan. Pembahasannya mencakup faktor yang memengaruhi perkembangan, kebutuhan psikologis remaja, serta peran lingkungan keluarga, sekolah, dan masyarakat dalam mendukung perkembangan kepribadian remaja.','2026-07-31 12:46:06','2026-08-09 22:50:51'),(87,1,'Psikologi Pendidikan dengan Pendekatan Baru','Buku Psikologi Pendidikan dengan Pendekatan Baru membahas penerapan ilmu psikologi dalam dunia pendidikan. Materinya mencakup perkembangan peserta didik, proses belajar, faktor yang memengaruhi keberhasilan belajar, motivasi, kecerdasan, serta peran guru dalam menciptakan pembelajaran yang efektif.',10,'Muhibbin Syah','PT Remaja Rosdakarya','2014',3,0,'tersedia',NULL,'Buku ini menyajikan kajian psikologi pendidikan yang berhubungan dengan proses pembelajaran dan perkembangan manusia. Pembahasan diarahkan untuk membantu pendidik memahami karakteristik siswa, meningkatkan kualitas pengajaran, serta menciptakan lingkungan belajar yang mendukung perkembangan peserta didik.','2026-07-31 12:52:13','2026-08-09 22:50:51'),(88,1,'Menyemai Benih Teknologi Pendidikan','Buku Menyemai Benih Teknologi Pendidikan membahas konsep, perkembangan, dan penerapan teknologi dalam bidang pendidikan. Buku ini menjelaskan bagaimana teknologi dapat digunakan untuk meningkatkan kualitas pembelajaran melalui pengelolaan sumber belajar, media pembelajaran, dan inovasi pendidikan.',10,'Yusufhadi Miarso','Kencana Prenada Media Group,','2004',3,0,'tersedia',NULL,'Buku ini menyajikan kajian tentang teknologi pendidikan sebagai bidang ilmu yang mendukung proses belajar mengajar. Pembahasannya mencakup teori belajar, desain pembelajaran, media pendidikan, serta pemanfaatan teknologi untuk menciptakan pembelajaran yang efektif dan efisien.','2026-07-31 12:54:23','2026-08-09 22:50:51'),(89,1,'Ibu, Maafkan Aku','Buku Ibu, Maafkan Aku menceritakan hubungan kasih sayang antara anak dan ibu. Kisah ini menggambarkan penyesalan seorang anak atas kesalahan yang dilakukan serta pentingnya meminta maaf, menghargai, dan menyayangi orang tua.',3,'titin rosdiani','.','.',4,0,'tersedia',NULL,'Buku ini menyampaikan pesan moral tentang kasih sayang keluarga, rasa hormat kepada ibu, dan pentingnya sikap rendah hati untuk mengakui kesalahan. Cerita dalam buku ini mengajarkan nilai karakter seperti tanggung jawab, kejujuran, dan cinta kepada keluarga.','2026-07-31 12:57:52','2026-08-09 22:50:51'),(90,1,'Panduan Guru Ilmu Pengetahuan Alam untuk SMP/MTs Kelas VII (Kurikulum Merdeka)','Buku Panduan Guru Ilmu Pengetahuan Alam Kelas VII berisi pedoman bagi guru dalam melaksanakan pembelajaran IPA sesuai Kurikulum Merdeka. Buku ini membantu guru menyusun strategi pembelajaran, kegiatan praktikum, asesmen, serta pendekatan pembelajaran yang sesuai dengan karakteristik peserta didik.',1,'Victoriani Inabuy, Cece Sutia, Okky Fajar Tri Maryana, Dwi Hardanie, Sri Handayani Lestari, dan Budiyanti.','Pusat Perbukuan, Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi Republik Indonesia.','2023',3,0,'tersedia',NULL,'Buku ini membahas metode dan strategi pembelajaran IPA yang menggabungkan pemahaman konsep, fakta, teori, serta keterampilan proses sains. Materinya mencakup capaian pembelajaran, alur tujuan pembelajaran, strategi mengajar, asesmen, dan penggunaan Buku Siswa untuk mendukung pembelajaran yang efektif.','2026-07-31 13:02:01','2026-08-09 22:50:51'),(91,1,'Seni Budaya SMP/MTs Kelas VII ΓÇô Buku Guru','Buku Seni Budaya SMP/MTs Kelas VII Buku Guru berisi panduan bagi guru dalam mengajarkan mata pelajaran Seni Budaya. Buku ini mencakup pembelajaran seni rupa, seni musik, seni tari, dan seni teater dengan berbagai strategi, metode, serta kegiatan kreatif yang dapat diterapkan di kelas.',1,'Eko Purnomo, Deden Haerudin, Buyung Rohmanto, dan Julius Juih','Pusat Kurikulum dan Perbukuan, Badan Penelitian dan Pengembangan, Kementerian Pendidikan dan Kebudayaan Republik Indonesia','2017',3,0,'tersedia',NULL,'Buku ini disusun untuk membantu guru mengembangkan pembelajaran Seni Budaya yang mencakup aspek pengetahuan, keterampilan, dan sikap. Materinya memberikan arahan mengenai perencanaan pembelajaran, aktivitas berkarya seni, penilaian, serta pengembangan kreativitas peserta didik melalui seni budaya.','2026-07-31 13:04:10','2026-08-09 22:50:51'),(92,1,'Kamus Komputer','Buku Kamus Komputer berisi kumpulan istilah-istilah dalam bidang komputer beserta penjelasannya. Buku ini membantu pembaca memahami berbagai istilah teknologi, perangkat keras, perangkat lunak, pemrograman, dan konsep dasar komputer.',2,'Claude P. Wrathall','PT Rineka Cipta,','2017',3,0,'tersedia',NULL,'Buku ini disusun sebagai sumber referensi untuk mengenal istilah komputer secara lebih mudah dan sistematis. Materinya mencakup berbagai kata, singkatan, dan istilah teknis komputer yang digunakan dalam perkembangan teknologi informasi.','2026-07-31 13:07:29','2026-07-31 13:07:29'),(93,1,'Belajar Bermain Futsal','Buku Belajar Bermain Futsal membahas pengenalan permainan futsal, aturan dasar, teknik bermain, strategi sederhana, serta keterampilan dasar seperti mengoper bola, menggiring bola, menembak, dan kerja sama tim. Buku ini membantu pembaca memahami cara bermain futsal dengan baik dan benar.',5,'Sukirno, S.Pd','CV Arya Duta,','2010',3,0,'tersedia',NULL,'Buku ini berisi panduan dasar olahraga futsal yang dirancang untuk mengenalkan teknik dan keterampilan bermain futsal kepada siswa. Materinya mencakup konsep permainan, latihan dasar, serta pembentukan kemampuan fisik dan kerja sama dalam bermain futsal.','2026-07-31 13:09:40','2026-07-31 13:09:40'),(94,1,'Kreasi Mendaur Ulang Sampah','Buku Kreasi Mendaur Ulang Sampah membahas cara memanfaatkan sampah dan barang bekas menjadi berbagai karya kreatif yang memiliki nilai guna. Buku ini memberikan contoh pembuatan kerajinan dari bahan bekas seperti plastik, kertas, dan barang rumah tangga lainnya melalui langkah-langkah sederhana.',4,'ade husnul','arya duta','2015',3,0,'tersedia',NULL,'Buku ini berisi panduan kreativitas dalam mengolah sampah melalui konsep reduce, reuse, dan recycle (3R). Pembaca diajak mengembangkan keterampilan membuat barang bermanfaat dari limbah sekaligus meningkatkan kepedulian terhadap kebersihan dan kelestarian lingkungan.','2026-07-31 13:13:46','2026-08-09 22:50:51'),(95,1,'Aku Menanam Pohon','Buku Aku Menanam Pohon menceritakan kepedulian seorang anak terhadap lingkungan melalui kegiatan menanam pohon. Cerita ini mengajarkan pentingnya menjaga alam, mencintai tumbuhan, dan melakukan kegiatan sederhana yang bermanfaat bagi bumi.',2,'maya rahmayanti','arya duta','2017',4,0,'tersedia',NULL,'Buku ini menyampaikan pesan tentang pelestarian lingkungan melalui kebiasaan menanam dan merawat pohon. Melalui cerita sederhana, pembaca diajak memahami manfaat pohon bagi kehidupan serta membangun sikap peduli terhadap alam.','2026-07-31 13:52:15','2026-08-09 22:50:51'),(96,1,'Bersahabat dengan Kucing','Buku Bersahabat dengan Kucing mengenalkan cara memahami dan merawat kucing sebagai hewan peliharaan. Buku ini membahas karakteristik kucing, cara memberi makan, menjaga kebersihan, serta cara membangun hubungan yang baik antara manusia dan kucing.',2,'WN. Suryadi dan Sulinah','CV Arya Duta','2010',3,0,'tersedia',NULL,'Buku ini berisi pengetahuan dasar tentang kehidupan dan perawatan kucing. Melalui penjelasan sederhana, pembaca diajak mengenal perilaku kucing, menyayangi hewan, serta bertanggung jawab dalam memelihara makhluk hidup','2026-07-31 13:53:59','2026-07-31 13:53:59'),(97,1,'Iklim yang Tidak Menentu','Buku Iklim yang Tidak Menentu membahas perubahan kondisi iklim yang terjadi di bumi akibat berbagai faktor lingkungan. Buku ini menjelaskan penyebab perubahan iklim, dampaknya terhadap kehidupan manusia, cuaca ekstrem, serta pentingnya menjaga lingkungan untuk mengurangi kerusakan alam.',3,'andri kusmayadi','arya duta','2017',3,0,'tersedia',NULL,'Buku ini menyajikan pengetahuan tentang perubahan iklim dan pengaruhnya terhadap kehidupan. Pembahasannya mencakup pemanasan global, perubahan cuaca, dampak terhadap lingkungan, serta upaya manusia dalam menjaga keseimbangan alam.','2026-07-31 13:56:21','2026-08-09 22:50:51'),(98,1,'Mengenal Lingkungan yang Sehat','Buku Mengenal Lingkungan yang Sehat membahas pengertian lingkungan sehat, ciri-ciri lingkungan yang bersih, serta cara menjaga kebersihan lingkungan. Buku ini mengajak pembaca memahami hubungan antara lingkungan yang sehat dengan kesehatan manusia melalui kebiasaan hidup bersih dan peduli terhadap alam.',3,'m syamsul','arya duta','2017',3,0,'tersedia',NULL,'Buku ini menyajikan pengetahuan dasar tentang lingkungan sehat, meliputi kebersihan udara, air, pengelolaan sampah, dan perilaku hidup sehat. Materinya bertujuan menanamkan kesadaran kepada pembaca agar menjaga lingkungan demi terciptanya kehidupan yang nyaman dan sehat.','2026-07-31 13:58:59','2026-08-09 22:50:51'),(99,1,'Getaran dan Gelombang','Buku Getaran dan Gelombang membahas konsep dasar fisika mengenai getaran dan gelombang, seperti getaran harmonik, frekuensi, amplitudo, periode, gelombang transversal, gelombang longitudinal, gelombang bunyi, serta penerapannya dalam kehidupan sehari-hari. Buku ini disusun untuk membantu memahami fenomena fisika yang berkaitan dengan gerak dan perpindahan energi.',4,'Arif Hidayat','Media Nusa Creative (MNC Publishing)','2021',3,0,'tersedia',NULL,'Buku ini menyajikan pembahasan mengenai teori dan konsep getaran serta gelombang secara sistematis. Materinya mencakup prinsip dasar osilasi, gelombang mekanik, gelombang bunyi, dan berbagai fenomena fisika yang berkaitan dengan perambatan energi. Buku ini dapat menjadi referensi pembelajaran fisika bagi mahasiswa maupun pembaca yang ingin memahami konsep getaran dan gelombang.','2026-07-31 14:01:17','2026-08-09 22:50:51'),(100,1,'Bumi Manusia','Novel Bumi Manusia menceritakan kehidupan seorang pemuda bernama Minke pada masa penjajahan Belanda. Minke berjuang menghadapi ketidakadilan sosial, perbedaan kelas, dan tekanan kolonial sambil mencari jati diri sebagai seorang manusia yang merdeka.',2,'Pramoedya Ananta Toer','Hasta Mitra','1980',4,0,'tersedia',NULL,'Buku ini menggambarkan perjuangan manusia dalam menghadapi penindasan dan ketidakadilan pada masa kolonial. Melalui kisah Minke, pembaca diajak memahami pentingnya pendidikan, keberanian, kebebasan berpikir, dan perjuangan untuk memperoleh kesetaraan.','2026-07-31 14:06:38','2026-08-09 22:50:51'),(101,1,'laskar pelangi','Novel Laskar Pelangi menceritakan perjuangan sepuluh anak di Belitung yang bersekolah dengan berbagai keterbatasan. Mereka tetap memiliki semangat belajar, persahabatan yang kuat, dan impian besar untuk meraih masa depan yang lebih baik. Kisah ini menggambarkan pentingnya pendidikan, kerja keras, dan pantang menyerah.',3,'Andrea Hirata','benteng pustaka','2005',4,0,'tersedia',NULL,'Buku ini menggambarkan kehidupan anak-anak sederhana yang berjuang mendapatkan pendidikan di tengah kondisi yang sulit. Melalui kisah persahabatan dan perjuangan mereka, pembaca diajak memahami nilai semangat, keberanian bermimpi, dan pentingnya pendidikan.','2026-07-31 14:08:16','2026-08-09 22:50:51'),(102,1,'Laut Bercerita','Novel Laut Bercerita mengisahkan kehidupan Laut Biru, seorang mahasiswa aktivis yang mengalami peristiwa penculikan akibat perjuangannya melawan ketidakadilan. Cerita ini menggambarkan persahabatan, keluarga, perjuangan, serta harapan untuk mendapatkan keadilan.',3,'Leila S. Chudori','Kepustakaan Populer Gramedia (KPG)','2017',4,0,'tersedia',NULL,'Buku ini mengangkat kisah fiksi berlatar peristiwa sosial dan politik Indonesia. Melalui sudut pandang para tokohnya, novel ini menggambarkan nilai keberanian, kemanusiaan, kehilangan, dan perjuangan mempertahankan kebenaran.','2026-07-31 14:10:17','2026-08-09 22:50:51'),(103,1,'hujan','Hujan menceritakan kisah Lail, seorang gadis yang hidup setelah terjadi bencana besar yang mengubah dunia. Dalam perjalanan hidupnya, Lail menghadapi kehilangan, perubahan, persahabatan, dan berbagai pilihan sulit untuk menemukan arti kehidupan.',2,'Tere Liye','Gramedia Pustaka Utama','2016',4,0,'tersedia',NULL,'Hujan mengangkat tema kehidupan manusia, teknologi, cinta, dan harapan di masa depan. Novel ini memberikan pesan tentang keteguhan hati, keikhlasan, serta pentingnya menghargai setiap kenangan dalam kehidupan.','2026-07-31 14:14:12','2026-08-09 22:50:51'),(104,1,'komet','Novel Komet menceritakan petualangan Raib, Seli, dan Ali dalam perjalanan menuju dunia paralel yang penuh misteri. Mereka menghadapi berbagai tantangan, bertemu makhluk unik, dan berusaha menyelesaikan misi dengan keberanian serta kerja sama',2,'Tere Liye','Gramedia Pustaka Utama','2018',4,0,'tersedia',NULL,'Buku Komet merupakan novel fantasi yang menggabungkan unsur petualangan, persahabatan, dan imajinasi. Cerita ini mengajarkan nilai keberanian, kesetiaan, dan kerja sama dalam menghadapi berbagai rintangan.','2026-07-31 14:16:56','2026-08-09 22:50:51'),(105,1,'Si Anak Cahaya','Novel Si Anak Cahaya menceritakan perjalanan hidup seorang anak bernama Nurmas yang tumbuh dalam keluarga sederhana. Kisah ini menggambarkan perjuangan, kasih sayang keluarga, persahabatan, dan pengalaman hidup yang membentuk karakter seseorang.',2,'Tere Liye','Republika Penerbit','2018',4,0,'tersedia',NULL,'Buku Si Anak Cahaya menyajikan cerita inspiratif tentang kehidupan anak dengan latar budaya dan keluarga. Novel ini mengajarkan nilai kebaikan, ketulusan, kerja keras, serta pentingnya menghargai keluarga dan lingkungan sekitar.','2026-07-31 14:18:27','2026-08-09 22:50:51'),(106,1,'Selena','Novel Selena menceritakan kisah masa muda Selena, seorang guru matematika di dunia paralel. Cerita ini mengungkap perjalanan hidupnya, perjuangan meraih cita-cita, serta berbagai pengalaman yang membentuk dirinya menjadi sosok yang kuat.',2,'Tere Liye','Gramedia Pustaka Utama','2020',4,0,'tersedia',NULL,'Buku Selena merupakan novel fantasi remaja yang mengangkat tema pendidikan, persahabatan, perjuangan, dan pencarian jati diri. Melalui kisah tokoh utama, pembaca diajak memahami arti kerja keras dan keberanian menghadapi tantangan hidup.','2026-07-31 14:20:34','2026-08-09 22:50:51'),(107,1,'Timun Mas','Timun Mas menceritakan seorang gadis bernama Timun Mas yang lahir dari sebuah timun emas pemberian raksasa kepada seorang janda bernama Mbok Sirni. Ketika dewasa, Timun Mas harus melarikan diri dari kejaran raksasa yang ingin mengambilnya. Dengan bantuan benda-benda ajaib, Timun Mas berhasil mengalahkan raksasa tersebut.',1,'.R. A. Kosasih','.','2018',4,0,'tersedia',NULL,'Dongeng Timun Mas merupakan cerita rakyat Jawa yang mengandung pesan moral tentang keberanian, kecerdikan, dan pantang menyerah. Kisah ini mengajarkan bahwa dengan usaha, doa, dan keberanian seseorang dapat menghadapi berbagai kesulitan.','2026-07-31 14:25:42','2026-08-09 22:50:51'),(108,1,'Sangkuriang','Buku Sangkuriang menceritakan kisah seorang pemuda bernama Sangkuriang yang tidak mengetahui bahwa Dayang Sumbi adalah ibu kandungnya. Karena sebuah kesalahan dan kemarahan, Sangkuriang harus menghadapi konflik besar hingga akhirnya muncul legenda terbentuknya Gunung Tangkuban Perahu.',1,'Tira Ikranegara','Serba Jaya','.',4,0,'tersedia',NULL,'Cerita Sangkuriang merupakan dongeng rakyat dari Jawa Barat yang mengandung pesan moral tentang pentingnya menghormati orang tua, mengendalikan emosi, dan berpikir sebelum bertindak. Kisah ini memperkenalkan budaya serta legenda Indonesia kepada pembaca.','2026-07-31 14:29:59','2026-08-09 22:50:51'),(109,1,'Mengenal Windows XP','Buku Mengenal Windows XP membahas pengenalan dasar sistem operasi Microsoft Windows XP. Buku ini menjelaskan cara menggunakan komputer, mengenal tampilan Windows, mengelola file, menjalankan program, serta memanfaatkan berbagai fitur dasar Windows XP.',20,'M.S. Maggie Key','andi','2008',3,0,'tersedia',NULL,'Buku ini berisi panduan sederhana untuk mengenal dan menggunakan sistem operasi Windows XP bagi pemula. Pembahasan mencakup fungsi dasar komputer, pengoperasian menu Windows, pengaturan sistem, dan penggunaan aplikasi pendukung sehingga pembaca dapat memahami teknologi komputer dengan mudah.','2026-07-31 14:34:54','2026-08-09 22:50:51'),(110,1,'Menjadi Guru Sukses dan Profesional','Buku Menjadi Guru Sukses dan Profesional membahas berbagai kompetensi yang harus dimiliki oleh seorang guru agar mampu menjalankan tugasnya secara profesional. Penulis menguraikan peran guru sebagai pendidik, pengajar, pembimbing, dan motivator, disertai penjelasan mengenai strategi pembelajaran, pengelolaan kelas, evaluasi hasil belajar, serta pengembangan kepribadian guru. Buku ini menjadi salah satu referensi penting bagi mahasiswa pendidikan maupun guru dalam meningkatkan kualitas pembelajaran.',2,'M. Uzer Usma','PT Remaja Rosdakarya','2013',3,0,'tersedia',NULL,'Buku ini mengkaji konsep profesionalisme guru berdasarkan kompetensi pedagogik, profesional, kepribadian, dan sosial. Pembahasannya menekankan pentingnya penguasaan materi, metode pembelajaran, pengelolaan kelas, evaluasi, serta etika profesi untuk menciptakan proses pembelajaran yang efektif. Buku ini bertujuan menjadi pedoman bagi calon guru dan guru dalam meningkatkan mutu pendidikan melalui pengembangan kompetensi secara berkelanjutan.','2026-08-01 06:56:01','2026-08-09 22:50:51'),(111,1,'Sabar Tanpa Tepi, Ikhlas Tanpa Tap','Buku ini menjelaskan bahwa sikap sabar dan ikhlas merupakan kunci menghadapi berbagai ujian kehidupan. Penulis menguraikan makna sabar dan ikhlas menurut ajaran Islam, disertai contoh penerapan dalam kehidupan sehari-hari agar pembaca mampu menghadapi kesulitan, menjaga ketenangan hati, dan semakin mendekatkan diri kepada Allah SWT.',3,'Deni Sutan Bahtiar','Araska Publishe','2023',3,0,'tersedia',NULL,'Buku ini membahas konsep sabar dan ikhlas sebagai nilai utama dalam membentuk karakter seorang muslim. Materi disajikan berdasarkan Al-Qur\'an dan Hadis dengan penjelasan mengenai pentingnya kesabaran dalam menghadapi cobaan, serta keikhlasan dalam menerima ketentuan Allah. Buku ini bertujuan memberikan pemahaman dan motivasi agar pembaca mampu menjalani kehidupan dengan hati yang lebih tenang dan penuh rasa syukur.','2026-08-01 06:57:55','2026-08-01 06:57:55'),(112,1,'Membangun Komunikasi Bijak','Buku ini membahas pentingnya membangun komunikasi yang sehat antara orang tua dan anak dalam keluarga. Penulis menjelaskan berbagai cara menjalin hubungan yang harmonis melalui keterbukaan, saling menghargai, empati, dan komunikasi yang efektif. Selain itu, buku ini memberikan contoh-contoh situasi yang sering terjadi dalam kehidupan keluarga beserta solusi yang dapat diterapkan untuk menciptakan hubungan yang lebih baik.',3,'Henny Djuanda, Clara Wresti, dan tim','Penerbit Buku Kompas','2007',3,0,'tersedia',NULL,'Buku ini mengulas prinsip-prinsip komunikasi keluarga yang efektif sebagai dasar terciptanya hubungan yang harmonis antara orang tua dan anak. Materi disajikan dalam bentuk teori dan contoh penerapan komunikasi sehari-hari untuk membantu keluarga mengatasi konflik, meningkatkan rasa saling percaya, serta membangun lingkungan keluarga yang mendukung perkembangan anak. Buku ini cocok dijadikan referensi bagi orang tua, pendidik, maupun siswa yang ingin memahami pentingnya komunikasi dalam keluarga.','2026-08-01 07:03:23','2026-08-09 22:50:51'),(113,1,'IPS Terpadu SMP/MTs Kelas VII: Perkembangan Masyarakat pada Masa Hindu-Buddha di Indonesia','Buku ini membahas perkembangan masyarakat Indonesia pada masa Hindu-Buddha, mulai dari masuknya pengaruh agama dan kebudayaan Hindu-Buddha ke Nusantara, berdirinya kerajaan-kerajaan seperti Kutai, Tarumanegara, Sriwijaya, Mataram Kuno, Kediri, Singasari, dan Majapahit, hingga perkembangan kehidupan sosial, ekonomi, budaya, serta peninggalan sejarah berupa candi, prasasti, dan karya sastra. Materi disusun secara sistematis agar siswa mudah memahami perjalanan sejarah Indonesia pada masa tersebut.',20,'Mukminan, Endang Mulyani, dan Tim Penulis','Erlangga','2008',3,0,'tersedia',NULL,'Buku ini menjelaskan proses berkembangnya masyarakat Indonesia pada masa Hindu-Buddha melalui pembahasan mengenai masuknya pengaruh Hindu-Buddha, perkembangan kerajaan-kerajaan, kehidupan politik, ekonomi, sosial, budaya, dan hasil-hasil kebudayaan yang masih dapat dijumpai hingga saat ini. Materi disajikan sesuai kurikulum IPS SMP untuk membantu peserta didik memahami perubahan masyarakat Indonesia pada masa Hindu-Buddha secara kronologis dan menyeluruh.','2026-08-01 07:15:16','2026-08-09 22:50:51'),(114,1,'Prakarya SMP/MTs Kelas VII (Kurikulum 2013 Edisi Revisi)','Buku ini membahas berbagai materi prakarya dan kerajinan tangan untuk siswa SMP, seperti kerajinan dari bahan serat, tekstil, kertas, dan plastik. Selain mempelajari teknik pembuatan kerajinan, siswa juga diajak mengenal proses perancangan produk, penggunaan alat dan bahan, serta cara menghasilkan karya yang kreatif, fungsional, dan bernilai ekonomis. Materi disajikan dengan bahasa yang sederhana serta dilengkapi latihan dan proyek praktik.',15,'Dian Novitarini','Bumi Aksara','2019',3,0,'tersedia',NULL,'Buku Prakarya SMP/MTs Kelas VII merupakan buku pembelajaran yang bertujuan mengembangkan pengetahuan, keterampilan, kreativitas, dan jiwa kewirausahaan peserta didik melalui kegiatan kerajinan tangan. Materi mencakup pengenalan berbagai bahan kerajinan, teknik pembuatan produk, pengolahan limbah menjadi karya yang bermanfaat, serta kegiatan proyek untuk melatih kemampuan berpikir kreatif dan inovatif sesuai Kurikulum 2013.','2026-08-01 07:19:05','2026-08-09 22:50:51'),(115,2,'Matematika untuk SMP/MTs Kelas VIII (Kurikulum Merdeka)','Buku ini membahas berbagai materi matematika kelas VIII, salah satunya Statistika. Pada bab statistika, siswa mempelajari cara mengumpulkan, menyajikan, dan mengolah data dalam bentuk tabel, diagram batang, diagram garis, diagram lingkaran, serta menghitung ukuran pemusatan data seperti rata-rata (mean), median, dan modus. Materi dilengkapi contoh soal, latihan, dan kegiatan yang membantu siswa memahami penerapan statistika dalam kehidupan sehari-hari.',20,'Tim Penulis Pusat Perbukuan Kemendikbudristek','Pusat Perbukuan, Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi','2022',3,0,'tersedia',NULL,'Buku ini menyajikan materi statistika sebagai bagian dari pembelajaran matematika SMP yang bertujuan mengembangkan kemampuan peserta didik dalam mengumpulkan, menyajikan, menganalisis, dan menafsirkan data. Pembelajaran disusun secara bertahap melalui penjelasan konsep, contoh kontekstual, serta latihan soal sehingga siswa mampu menerapkan statistika untuk memecahkan masalah sehari-hari dan mendukung kemampuan berpikir kritis.','2026-08-01 07:25:13','2026-08-09 22:50:51'),(116,NULL,'Apa Itu Diksus?','Pengenalan tentang Pendidikan Khusus (Diksus) bagi siswa dan guru.',3,'Kemdikbud','Kemdikbud','2023',NULL,0,'tersedia',NULL,'Buku referensi mengenai konsep dan praktik pendidikan khusus di Indonesia.','2026-08-08 01:42:45','2026-08-08 01:42:45'),(117,1,'Informatika Kelas VII (Buku Siswa)','Buku siswa mata pelajaran Informatika Kurikulum Merdeka untuk kelas VII SMP.',10,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2021',3,0,'tersedia','foto_buku/0xCkkuVNakcK1AuhqyxUhGOZRmquTVPEp9yGZzGc.png','Membahas literasi digital, berpikir komputasional, dan pengenalan perangkat TIK.','2026-08-08 01:42:45','2026-08-09 18:59:51'),(118,1,'Ilmu Pengetahuan Alam Kelas VII (Buku Siswa)','Buku siswa IPA Kurikulum Merdeka revisi untuk kelas VII SMP.',12,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2022',NULL,0,'tersedia',NULL,'Meliputi materi makhluk hidup, zat dan perubahannya, serta energi.','2026-08-08 01:42:45','2026-08-08 01:42:45'),(119,3,'Informatika Kelas IX (Buku Siswa)','Buku siswa Informatika Kurikulum Merdeka revisi untuk kelas IX SMP.',10,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2023',NULL,0,'tersedia',NULL,'Pemrograman dasar, kecerdasan buatan, dan keamanan digital.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(120,2,'Informatika Kelas VIII (Buku Siswa)','Buku siswa Informatika Kurikulum Merdeka revisi untuk kelas VIII SMP.',10,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2022',NULL,0,'tersedia',NULL,'Topik meliputi jaringan komputer, algoritma, dan pengolahan data.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(121,1,'Matematika Kelas VII (Buku Siswa)','Buku siswa Matematika Kurikulum Merdeka untuk kelas VII SMP.',15,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2021',NULL,0,'tersedia',NULL,'Meliputi bilangan bulat, himpunan, aljabar, dan geometri dasar.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(122,2,'Matematika Kelas VIII (Buku Siswa)','Buku siswa Matematika Kurikulum Merdeka untuk kelas VIII SMP.',15,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2022',NULL,0,'tersedia',NULL,'Membahas sistem persamaan linear, fungsi, teorema Pythagoras, dan statistika.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(123,3,'Matematika Kelas IX (Buku Siswa)','Buku siswa Matematika Kurikulum Merdeka untuk kelas IX SMP.',15,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2023',NULL,0,'tersedia',NULL,'Topik meliputi bilangan berpangkat, transformasi, peluang, dan statistika lanjut.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(124,1,'PJOK Kelas VII (Buku Siswa)','Buku siswa Pendidikan Jasmani, Olahraga, dan Kesehatan untuk kelas VII SMP.',10,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2021',NULL,0,'tersedia',NULL,'Meliputi gerak dasar olahraga, permainan, dan kesehatan remaja.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(125,2,'PJOK Kelas VIII (Buku Siswa)','Buku siswa PJOK Kurikulum Merdeka untuk kelas VIII SMP.',10,'Kemendikbudristek','Pusat Kurikulum dan Perbukuan','2022',NULL,0,'tersedia',NULL,'Mencakup atletik, senam, aquatik, dan pola hidup sehat.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(128,NULL,'Pak Abad, Pengobat Tradisional','Kisah Pak Abad, seorang pengobat tradisional yang bijaksana di desanya.',5,'Kemdikbud','Kemdikbud','2023',NULL,0,'tersedia',NULL,'Buku bacaan fiksi bertema kearifan lokal untuk siswa SMP.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(129,NULL,'Putri Nibung di Sarang Lamun','Cerita rakyat Kalimantan tentang Putri Nibung yang tinggal di sarang lamun.',5,'Kemdikbud','Kemdikbud','2023',NULL,0,'tersedia',NULL,'Buku cerita rakyat Nusantara untuk siswa SMP.','2026-08-08 01:42:46','2026-08-08 01:42:46'),(130,NULL,'Sai Ngugha Si Pemberani','Kisah heroik Sai Ngugha, tokoh pemberani dari tradisi lisan Nusantara.',5,'Kemdikbud','Kemdikbud','2023',NULL,1,'tersedia',NULL,'Bacaan fiksi bertema keberanian dan nilai budaya lokal untuk SMP.','2026-08-08 01:42:46','2026-08-09 22:37:57');
